export default JSON.parse("{\"2.6.1\":{\"unit\":\"2.6\",\"courseId\":\"2.6.1\",\"bridge\":\"Unit 2.5 ended in 2.5.8 with lines near every price. Here you set them aside and read each bar. In 2.1.1 you measured a candle against its neighbours; now body and close sort bars, and overlap separates the trends and ranges of 1.5.2.\",\"hook\":{\"prompt\":\"Six bars in a row overlap heavily and have small bodies. Trend or range?\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100.1,\"h\":100.45,\"l\":99.8,\"c\":100.2},{\"o\":100.2,\"h\":100.5,\"l\":99.85,\"c\":100.05},{\"o\":100.05,\"h\":100.4,\"l\":99.75,\"c\":100.15},{\"o\":100.15,\"h\":100.55,\"l\":99.9,\"c\":100.1},{\"o\":100.1,\"h\":100.45,\"l\":99.8,\"c\":99.95},{\"o\":99.95,\"h\":100.4,\"l\":99.85,\"c\":100.1}]},\"steps\":[{\"text\":\"Six bars, each mostly inside the one before. The bodies are small next to the ranges.\"}]},\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"trend\",\"label\":\"Trend\",\"feedback\":\"A trend leaves bars behind: each bar shares little with the one before. These share most of their range.\"},{\"id\":\"range\",\"label\":\"Range\",\"feedback\":\"That's the reading: heavy overlap and small bodies show buyers and sellers roughly in balance.\"},{\"id\":\"unclear\",\"label\":\"Can't tell\",\"feedback\":\"Overlap and body size can be measured, and here both point the same way: a range.\"}],\"answer\":\"range\"},\"compare\":\"You picked {yours}. Those six bars overlapped by 88% on average, with small bodies: two-sided trading, a range reading.\",\"concept\":\"bar-reading\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"Price action reads each bar for who won it. A [[trend-bar]] has a body of at least half its range and closes in the third nearest its extreme. A [[doji-bar]] has a body of a quarter of its range or less: neither side won. [[bar-overlap|Overlap]] is how much of a bar's range the bar before also covered.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":101.05,\"l\":99.95,\"c\":101},{\"o\":101,\"h\":101.25,\"l\":100.45,\"c\":100.9}],\"visible\":1},\"steps\":[{\"text\":\"A bull trend bar: body 1.00 of a 1.10 range, closing 0.05 under the high.\",\"layers\":[{\"kind\":\"bracket\",\"from\":100,\"to\":101,\"index\":0,\"label\":\"BODY 1.00\"}]},{\"text\":\"A doji bar: body 0.10 of a 0.80 range. Neither side won the hour.\",\"visible\":2,\"layers\":[{\"kind\":\"bracket\",\"from\":100.9,\"to\":101,\"index\":1,\"label\":\"BODY 0.10\"}]},{\"text\":\"They share 100.45 to 101.05: 0.60, which is 75% of the smaller range, 0.80.\",\"layers\":[{\"kind\":\"zone\",\"from\":100.45,\"to\":101.05,\"role\":\"concept\",\"label\":\"OVERLAP 0.60\"}]}]}},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"A **doji bar** is broader than the candle doji of unit 2.1, whose body is nearly flat, about a tenth of a typical range. Here any body of a quarter of the range or less counts. These thresholds are the app's conventions, after Al Brooks: measurable, not laws.\"},{\"kind\":\"worked\",\"title\":\"Measuring overlap\",\"lines\":[\"Bar A: high 100.80, low 100.20. Range 0.60.\",\"Bar B: high 101.00, low 100.50. Range 0.50.\",\"Shared part: the lower high minus the higher low, 100.80 − 100.50 = 0.30.\",\"Divide by the smaller range: 0.30 ÷ 0.50.\",\"Overlap, in % = ?\"],\"ask\":{\"answer\":60,\"tolerance\":0.5,\"unit\":\"%\",\"feedback\":[{\"value\":50,\"text\":\"That divides by the larger range, 0.60. The rule uses the smaller bar: 0.30 ÷ 0.50.\"},{\"value\":0.6,\"text\":\"Right ratio; give it in percent: 0.6 is 60%.\"}],\"correct\":\"Right: 60%. Bar B spent most of its hour inside bar A's range.\"},\"after\":\"60%. Two bars that don't touch at all overlap 0%; a bar fully inside the other overlaps 100%.\",\"concept\":\"bar-reading\"},{\"kind\":\"predict\",\"title\":\"Overlap in a trend\",\"prompt\":\"Eleven bars of an uptrend. Estimate the average overlap of the last ten, each with the bar before it.\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":100,\"step\":5,\"unit\":\"%\",\"start\":50,\"answer\":20,\"tolerance\":10,\"feedback\":[{\"from\":0,\"to\":5,\"text\":\"Lower than it is. The doji bar in the middle shares 47% with each neighbour.\"},{\"from\":10,\"to\":30,\"text\":\"Close: the average is 19.8%.\"},{\"from\":35,\"to\":100,\"text\":\"Higher than it is. Each bar opens near the last close and pushes on, so most pairs share under 20%.\"}]},\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.43,\"l\":99.98,\"c\":100.4},{\"o\":100.4,\"h\":100.84,\"l\":100.37,\"c\":100.82},{\"o\":100.82,\"h\":101.22,\"l\":100.8,\"c\":101.18},{\"o\":101.18,\"h\":101.65,\"l\":101.14,\"c\":101.62},{\"o\":101.62,\"h\":102.02,\"l\":101.6,\"c\":102},{\"o\":102,\"h\":102.18,\"l\":101.88,\"c\":102.06},{\"o\":102.06,\"h\":102.5,\"l\":102.04,\"c\":102.47},{\"o\":102.47,\"h\":102.86,\"l\":102.44,\"c\":102.84},{\"o\":102.84,\"h\":103.31,\"l\":102.82,\"c\":103.27},{\"o\":103.27,\"h\":103.69,\"l\":103.25,\"c\":103.66},{\"o\":103.66,\"h\":104.08,\"l\":103.63,\"c\":104.06}]},\"steps\":[{\"text\":\"Eight of the ten pairs share under 20%: each bar opens near the last close and pushes on.\"},{\"text\":\"The doji bar shares 47% with each neighbour. The average of all ten: 19.8%.\",\"layers\":[{\"kind\":\"marker\",\"index\":5,\"at\":\"high\",\"label\":\"DOJI\",\"role\":\"concept\"}]}]},\"reveal\":\"19.8%, under 30%: a trend reading. The six bars from the start averaged 88%, over 50%: a range reading. Between 30% and 50%, overlap alone doesn't decide. Two runs of five bull trend bars add to the trend reading: three or more in a row show urgency.\",\"concept\":\"bar-reading\"},{\"kind\":\"match\",\"prompt\":\"Match each 10-bar stretch to its reading.\",\"columns\":[\"Stretch\",\"Reading\"],\"pairs\":[{\"left\":\"Five bull trend bars in a row; average overlap 12%\",\"right\":\"Strong trend\",\"wrong\":\"A run of trend bars with little overlap is the strongest reading. Weak trends mix in doji bars and more overlap.\"},{\"left\":\"Higher highs, but bull, bear and doji bars mix; overlap 42%\",\"right\":\"Weak trend\",\"wrong\":\"There's a direction, higher highs, but mixed bars and 42% overlap make it a weak one.\"},{\"left\":\"Small bodies, overlap 66%, the same highs and lows again and again\",\"right\":\"Range\",\"wrong\":\"High overlap and repeated highs and lows are two-sided trading: a range.\"},{\"left\":\"Twelve overlapping bars, then two bull trend bars closing above all their highs\",\"right\":\"Breakout\",\"wrong\":\"The overlap belongs to the range before. What's new is two trend bars closing beyond it: a breakout attempt.\"}],\"correct\":\"Runs of trend bars and overlap tell them apart. A breakout still needs follow-through to last.\",\"concept\":\"bar-reading\"},{\"kind\":\"reveal\",\"title\":\"Same bar, different place\",\"prompt\":\"LABX has ranged between 99.50 and 100.50 for 12 bars. Bar 13 is a big bull trend bar closing at 100.55. On its own, what does it tell you?\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.3,\"l\":99.75,\"c\":99.9},{\"o\":99.9,\"h\":100.15,\"l\":99.6,\"c\":100.05},{\"o\":100.05,\"h\":100.45,\"l\":99.95,\"c\":100.35},{\"o\":100.35,\"h\":100.5,\"l\":100,\"c\":100.1},{\"o\":100.1,\"h\":100.2,\"l\":99.7,\"c\":99.8},{\"o\":99.8,\"h\":99.95,\"l\":99.5,\"c\":99.65},{\"o\":99.65,\"h\":100,\"l\":99.55,\"c\":99.95},{\"o\":99.95,\"h\":100.3,\"l\":99.85,\"c\":100.2},{\"o\":100.2,\"h\":100.4,\"l\":99.9,\"c\":100},{\"o\":100,\"h\":100.1,\"l\":99.6,\"c\":99.75},{\"o\":99.75,\"h\":100.05,\"l\":99.65,\"c\":99.95},{\"o\":99.95,\"h\":100.25,\"l\":99.85,\"c\":100.05},{\"o\":100.05,\"h\":100.6,\"l\":100,\"c\":100.55},{\"o\":100.55,\"h\":100.65,\"l\":100.25,\"c\":100.3},{\"o\":100.3,\"h\":100.4,\"l\":99.95,\"c\":100.05},{\"o\":100.05,\"h\":100.2,\"l\":99.8,\"c\":99.9},{\"o\":99.9,\"h\":100.15,\"l\":99.75,\"c\":100.05}],\"visible\":13,\"layers\":[{\"kind\":\"zone\",\"from\":99.5,\"to\":100.5,\"role\":\"neutral\",\"label\":\"RANGE\"}]},\"choices\":[{\"id\":\"trend\",\"label\":\"A new uptrend has started\",\"feedback\":\"One bar can't make a trend. Near the top of a range it meets sellers who have sold there for 12 bars.\"},{\"id\":\"wait\",\"label\":\"Little on its own: the next bars decide\",\"feedback\":\"Right. In a range, only follow-through turns a big bar into a breakout.\"},{\"id\":\"fade\",\"label\":\"It will fail, so sell it\",\"feedback\":\"That's a forecast from one bar too. Brooks expects most such bars to fail, but that's his estimate, not a measured rate.\"}],\"answer\":\"wait\",\"after\":\"The next four bars overlapped it and closed at 100.30, 100.05, 99.90 and 100.05, back inside. In a trend, the same bar would extend a run of trend bars. In a range, it often marks buyers arriving late, at the top.\",\"concept\":\"bar-reading\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"The measurements are mechanical: anyone gets the same numbers. Reading them as urgency or balance is Al Brooks' heuristic, with no published statistics: [[evidence-grade]] D. By his own account, most bars leave traders unsure, and most setups work 40–60% of the time.\"}],\"task\":{\"widget\":\"bias-spotter\",\"data\":{\"options\":[{\"id\":\"bull\",\"label\":\"Bull trend bar\"},{\"id\":\"bear\",\"label\":\"Bear trend bar\"},{\"id\":\"doji\",\"label\":\"Doji bar\"},{\"id\":\"neither\",\"label\":\"Neither\"}],\"cards\":[{\"id\":\"b1\",\"text\":\"Open 100.00, high 101.00, low 99.90, close 100.95.\",\"answer\":\"bull\",\"correct\":\"Body 0.95 of 1.10, 86%, and the close sits in the top third: a bull trend bar.\",\"rationales\":{\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.95 of a 1.10 range, 86%; close 100.95, top third from 100.63.\",\"doji\":\"A doji bar has a body of a quarter of the range or less. Here: body 0.95 of a 1.10 range, 86%; close 100.95, top third from 100.63.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.95 of a 1.10 range, 86%; close 100.95, top third from 100.63.\"}},{\"id\":\"b2\",\"text\":\"Open 100.50, high 100.90, low 100.10, close 100.55.\",\"answer\":\"doji\",\"correct\":\"Body 0.05 of 0.80, 6%: a doji bar. Price went both ways and ended where it began.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.05 of a 0.80 range, 6%.\",\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.05 of a 0.80 range, 6%.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.05 of a 0.80 range, 6%.\"}},{\"id\":\"b3\",\"text\":\"Open 100.20, high 100.80, low 100.00, close 100.50.\",\"answer\":\"neither\",\"correct\":\"Body 0.30 of 0.80, 38%: too big for a doji bar, too small for a trend bar.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.30 of a 0.80 range, 38%.\",\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.30 of a 0.80 range, 38%.\",\"doji\":\"A doji bar has a body of a quarter of the range or less. Here: body 0.30 of a 0.80 range, 38%.\"}},{\"id\":\"b4\",\"text\":\"Open 101.20, high 101.30, low 100.40, close 100.50.\",\"answer\":\"bear\",\"correct\":\"Body 0.70 of 0.90, 78%, closing in the bottom third: a bear trend bar.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.70 of a 0.90 range, 78%; close 100.50, bottom third up to 100.70.\",\"doji\":\"A doji bar has a body of a quarter of the range or less. Here: body 0.70 of a 0.90 range, 78%; close 100.50, bottom third up to 100.70.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.70 of a 0.90 range, 78%; close 100.50, bottom third up to 100.70.\"}},{\"id\":\"b5\",\"text\":\"Open 100.00, high 101.00, low 100.00, close 100.60.\",\"answer\":\"neither\",\"correct\":\"A big body, 60%, but the close, 100.60, sits mid-range, under 100.67. Sellers took back the top: neither.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.60 of a 1.00 range, 60%, but close 100.60 is under the top third, which starts at 100.67.\",\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.60 of a 1.00 range, 60%, but close 100.60 is under the top third, which starts at 100.67.\",\"doji\":\"A doji bar has a body of a quarter of the range or less. Here: body 0.60 of a 1.00 range, 60%, but close 100.60 is under the top third, which starts at 100.67.\"}},{\"id\":\"b6\",\"text\":\"Open 100.00, high 100.60, low 99.40, close 100.10.\",\"answer\":\"doji\",\"correct\":\"Body 0.10 of 1.20, 8%: a doji bar with long wicks both ways.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.10 of a 1.20 range, 8%.\",\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.10 of a 1.20 range, 8%.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.10 of a 1.20 range, 8%.\"}},{\"id\":\"b7\",\"text\":\"Open 100.80, high 100.85, low 100.00, close 100.10.\",\"answer\":\"bear\",\"correct\":\"Body 0.70 of 0.85, 82%, closing near the low: a bear trend bar.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.70 of a 0.85 range, 82%; close 100.10, bottom third up to 100.28.\",\"doji\":\"A doji bar has a body of a quarter of the range or less. Here: body 0.70 of a 0.85 range, 82%; close 100.10, bottom third up to 100.28.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.70 of a 0.85 range, 82%; close 100.10, bottom third up to 100.28.\"}},{\"id\":\"b8\",\"text\":\"Open 100.30, high 100.70, low 100.10, close 100.40.\",\"answer\":\"doji\",\"correct\":\"Body 0.10 of 0.60, 17%: under a quarter, so a doji bar.\",\"rationales\":{\"bull\":\"A bull trend bar needs a body of at least half the range and a close in the top third. Here: body 0.10 of a 0.60 range, 17%.\",\"bear\":\"A bear trend bar needs a body of at least half the range and a close in the bottom third. Here: body 0.10 of a 0.60 range, 17%.\",\"neither\":\"Neither is for bodies between a quarter and a half of the range, or big bodies closing mid-range. Here: body 0.10 of a 0.60 range, 17%.\"}}]},\"goal\":\"Eight bars. Classify each one by the app's rules: bull trend bar, bear trend bar, doji bar or neither.\",\"success\":{\"field\":\"solved\",\"eq\":8},\"correct\":\"All eight classified. Two numbers decide it: the body as a share of the range, then where the close sits.\",\"hints\":[\"Work out body ÷ range first: a quarter or less is a doji bar; half or more may be a trend bar.\",\"For a big body, check the close: top third for bull, bottom third for bear. Otherwise it's neither.\"],\"showMe\":{\"solved\":8},\"concept\":\"bar-reading\"},\"check\":[\"q-2.6.1-1\",\"q-2.6.1-2\",\"q-2.6.1-3\"],\"recap\":{\"takeaways\":[\"Trend bar: body at least half the range, close near the extreme. Doji bar: body a quarter or less.\",\"Average overlap under 30% suggests a trend, over 50% a range. Runs of trend bars show urgency.\",\"In a trend, a big trend bar adds to a run; inside a range it needs follow-through to mean much.\"],\"next\":\"Next, 2.6.2: one bar becomes a signal bar, the next an entry bar, and the trader's equation says whether it's worth it.\"}},\"2.6.2\":{\"unit\":\"2.6\",\"courseId\":\"2.6.2\",\"bridge\":\"In 2.6.1 you sorted bars by body and close. Here one bar becomes a signal: you grade it, buy one tick above it with the stop entry from 1.3.3, and check the trade with the break-even maths of 1.4.6, costs included.\",\"hook\":{\"prompt\":\"A setup wins 40% of the time. What is the smallest reward-to-risk that breaks even, before costs?\",\"control\":{\"kind\":\"numeric\",\"unit\":\": 1\",\"answer\":1.5,\"tolerance\":0.05,\"feedback\":[{\"value\":0.67,\"text\":\"That's 0.40 ÷ 0.60, upside down. The wins must pay for the losses: 0.60 ÷ 0.40.\"},{\"value\":2.5,\"text\":\"That's 1 ÷ 0.40. Break-even needs 0.40 × reward = 0.60 × 1.\"},{\"value\":1,\"text\":\"At 1:1, 40 wins of 1R can't pay for 60 losses of 1R.\"}]},\"compare\":\"You said {yours}. Break-even: 0.40 × reward = 0.60 × 1R, so the reward must be 1.5R. Below that, a 40% setup loses money even before costs.\",\"concept\":\"traders-equation\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"A [[signal-bar]] is the bar that sets up your trade. For a long, you place a buy [[stop-order|stop]] one tick, 0.01, above its high, and a protective stop one tick below its low. The bar in which the buy stop fills is the [[entry-bar]]. If price never trades above the signal bar, you never enter.\"},{\"kind\":\"figure\",\"title\":\"From signal bar to entry bar\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":101,\"h\":101.1,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.35,\"c\":100.45},{\"o\":100.45,\"h\":100.55,\"l\":100.25,\"c\":100.4},{\"o\":100.4,\"h\":100.9,\"l\":100.35,\"c\":100.85},{\"o\":100.85,\"h\":101.3,\"l\":100.8,\"c\":101.25},{\"o\":101.25,\"h\":101.6,\"l\":101.1,\"c\":101.2},{\"o\":101.2,\"h\":101.3,\"l\":100.9,\"c\":101},{\"o\":101,\"h\":101.05,\"l\":100.65,\"c\":100.7},{\"o\":100.7,\"h\":100.75,\"l\":100.3,\"c\":100.36},{\"o\":100.36,\"h\":100.8,\"l\":100.2,\"c\":100.72},{\"o\":100.72,\"h\":101.1,\"l\":100.65,\"c\":101.05},{\"o\":101.05,\"h\":101.3,\"l\":100.95,\"c\":101.25}],\"visible\":10},\"steps\":[{\"text\":\"Signal bar: a bull bar at the prior low, high 100.80, low 100.20.\",\"layers\":[{\"kind\":\"marker\",\"index\":2,\"at\":\"low\",\"label\":\"PRIOR LOW 100.25\",\"role\":\"concept\"},{\"kind\":\"marker\",\"index\":9,\"at\":\"low\",\"label\":\"SIGNAL BAR\",\"role\":\"concept\"}]},{\"text\":\"Buy stop at 100.81 and protective stop at 100.19: one tick beyond each end.\",\"layers\":[{\"kind\":\"level\",\"price\":100.81,\"role\":\"entry\",\"label\":\"BUY STOP 100.81\"},{\"kind\":\"level\",\"price\":100.19,\"role\":\"stop\",\"label\":\"STOP 100.19\"}]},{\"text\":\"Bar 11 trades through 100.81 and the order fills: that's the entry bar.\",\"visible\":11,\"layers\":[{\"kind\":\"marker\",\"index\":10,\"price\":100.81,\"label\":\"ENTRY BAR\",\"role\":\"accent\"}]},{\"text\":\"It closes at 101.05, near its high: the first information about the trade.\",\"layers\":[{\"kind\":\"marker\",\"index\":10,\"at\":\"close\",\"label\":\"CLOSE 101.05\",\"role\":\"up\"}]}]},\"text\":\"The gap between the two orders is your risk: 100.81 − 100.19 = 0.62 a unit, before slippage and costs.\",\"concept\":\"signal-and-entry-bars\"},{\"kind\":\"worked\",\"title\":\"Grade a signal bar\",\"lines\":[\"Five tests for a bull reversal signal bar, 1 point each.\",\"The bar: open 100.30, high 100.90, low 100.20, close 100.60. Range 0.70. ATR(14): 0.50.\",\"1. Bull body closing in the top third? The top third starts at 100.67.\",\"2. Lower wick at least 25% of the range? It's 0.10: 14%.\",\"3. Upper wick at most 15% of the range? It's 0.30: 43%.\",\"4. Range between 0.5 and 2 × ATR? 0.70 is 1.4 × ATR.\",\"5. At a location? It formed at the prior low, a support zone.\",\"Score, out of 5 = ?\"],\"ask\":{\"answer\":2,\"tolerance\":0,\"feedback\":[{\"value\":3,\"text\":\"Check test 1 again: the close, 100.60, is under 100.67, so it's not in the top third.\"},{\"value\":4,\"text\":\"Tests 1, 2 and 3 all fail: a mid-range close, a short lower wick, a long upper wick.\"},{\"value\":5,\"text\":\"Count only the tests it passes. A close at 100.60 under a wick to 100.90 fails three of them.\"}],\"correct\":\"Right: 2 of 5, tests 4 and 5.\"},\"after\":\"2 of 5: the right place, a weak bar. Sellers pushed it back from 100.90 and nothing shows buyers rejecting the low. The chart's signal bar passed tests 1–3: close 100.72 in its top third, a 0.16 tail below (27%), a 0.08 wick on top (13%).\",\"concept\":\"signal-and-entry-bars\"},{\"kind\":\"figure\",\"text\":\"The [[traders-equation|trader's equation]] checks a setup before you take it: chance of winning × reward must beat chance of losing × risk, after costs. It's the same arithmetic as [[expectancy]].\",\"figure\":{\"kind\":\"formula\",\"boxes\":[{\"text\":\"0.40 × 2R\"},{\"text\":\"0.60 × 1R\"},{\"text\":\"0.05R costs\"},{\"text\":\"edge\",\"answer\":0.15,\"tolerance\":0.001,\"unit\":\"R\"}],\"operators\":[\"−\",\"−\",\"=\"],\"steps\":[\"Wins: 40% of trades at +2R gives 0.80R.\",\"Losses: 60% at −1R gives 0.60R.\",\"Costs, spread and commission: about 0.05R a trade.\",\"What's left per trade? Type it, in R.\"]},\"concept\":\"traders-equation\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Brooks pairs probability with reward-to-risk: setups he rates near 60% need at least 1:1, and most reversals, near 40%, need at least 1:2. The probabilities are his subjective estimates. No published statistics show that higher-scoring signal bars win more often: [[evidence-grade]] D.\"},{\"kind\":\"predict\",\"prompt\":\"You rate a reversal at 40%. The stop is 0.62 below the entry and the target 0.62 above: 1:1. Take it?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"bar\",\"label\":\"Yes: the signal bar scored 5 of 5\",\"feedback\":\"A good bar doesn't fix the arithmetic: 0.40 × 1 − 0.60 × 1 = −0.20R a trade.\"},{\"id\":\"no\",\"label\":\"No: at 40%, 1:1 loses 0.20R a trade before costs\",\"feedback\":\"Right.\"},{\"id\":\"size\",\"label\":\"Yes, with a bigger size to make it worth it\",\"feedback\":\"Size scales the loss too: −0.20R a trade stays −0.20R, in bigger money.\"}],\"answer\":\"no\"},\"reveal\":\"0.40 × 1R − 0.60 × 1R = −0.20R a trade, before costs. At 40%, the target must sit at least 1.5R away to break even, and further to pay for costs. Move the target to where structure allows it, or skip the trade.\",\"concept\":\"traders-equation\"}],\"task\":{\"widget\":\"bracket-builder\",\"data\":{\"chart\":{\"candles\":[{\"o\":101,\"h\":101.1,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.35,\"c\":100.45},{\"o\":100.45,\"h\":100.55,\"l\":100.25,\"c\":100.4},{\"o\":100.4,\"h\":100.9,\"l\":100.35,\"c\":100.85},{\"o\":100.85,\"h\":101.3,\"l\":100.8,\"c\":101.25},{\"o\":101.25,\"h\":101.6,\"l\":101.1,\"c\":101.2},{\"o\":101.2,\"h\":101.3,\"l\":100.9,\"c\":101},{\"o\":101,\"h\":101.05,\"l\":100.65,\"c\":100.7},{\"o\":100.7,\"h\":100.75,\"l\":100.3,\"c\":100.36},{\"o\":100.36,\"h\":100.8,\"l\":100.2,\"c\":100.72}],\"layers\":[{\"kind\":\"marker\",\"index\":9,\"at\":\"low\",\"label\":\"SIGNAL BAR LOW 100.20\",\"role\":\"concept\"}]},\"entry\":100.81,\"units\":100},\"goal\":\"Your buy stop at 100.81 is the entry. Drag the protective stop one tick below the signal bar's low, and the target to 2R.\",\"start\":{\"stop\":99.9,\"target\":101.5,\"units\":100},\"locked\":[\"units\"],\"success\":{\"all\":[{\"field\":\"stop\",\"eq\":100.19},{\"field\":\"target\",\"eq\":102.05}]},\"feedback\":[{\"when\":{\"field\":\"stop\",\"eq\":100.2},\"text\":\"That's the bar's low itself. One tick below, 100.19, so a touch of the low doesn't stop you out.\"},{\"when\":{\"field\":\"stop\",\"gt\":100.2},\"text\":\"At {stop:2} the stop sits inside the signal bar. The idea is wrong only if price falls below its low, 100.20.\"},{\"when\":{\"field\":\"stop\",\"lt\":100.19},\"text\":\"At {stop:2} you risk {stopDistance:2} a unit. The idea fails below the signal bar's low, 100.20: one tick under is 100.19.\"},{\"when\":{\"field\":\"target\",\"ne\":102.05},\"text\":\"Stop right: 0.62 of risk. 2R is 2 × 0.62 = 1.24 above 100.81. You're at {rr:2}R.\"}],\"correct\":\"Risk 0.62 a unit, target 1.24 away: 2R. At 40%, that's +0.20R a trade before costs. A stop entry fills only if price trades through it, and in a fast market above 100.81.\",\"hints\":[\"One tick is 0.01, and the signal bar's low is 100.20.\",\"Risk = 100.81 − 100.19 = 0.62. The target sits twice that above the entry.\",\"Stop 100.19; target 100.81 + 1.24 = 102.05.\"],\"showMe\":{\"stop\":100.19,\"target\":102.05},\"concept\":\"signal-and-entry-bars\"},\"check\":[\"q-2.6.2-1\",\"q-2.6.2-2\",\"q-2.6.2-3\"],\"recap\":{\"takeaways\":[\"Grade a bull signal bar on five tests: close, lower tail, upper wick, size and location.\",\"Buy stop one tick above the signal bar, protective stop one tick below: the gap is your risk.\",\"Trader's equation: win chance × reward − loss chance × risk − costs must stay above zero.\"],\"next\":\"Next, 2.6.3: inside, outside and narrow-range bars, where one quiet bar sets up stop entries on both sides.\"}},\"2.6.3\":{\"unit\":\"2.6\",\"courseId\":\"2.6.3\",\"bridge\":\"In 2.6.2 you bought one tick above a signal bar. Here the signal is a quiet bar: an inside bar, the range version of the 2.1.4 harami, or an NR7, a small squeeze as in 2.4.8. You bracket it with OCO entries from 1.3.4.\",\"hook\":{\"prompt\":\"Two inside bars in a row: the range has shrunk to half the ATR. Is the next move more likely to be bigger or smaller than usual?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"bigger\",\"label\":\"A bigger move\",\"feedback\":\"That's the usual pattern for size: quiet spells tend to be followed by wider ranges. Direction is another matter.\"},{\"id\":\"smaller\",\"label\":\"A smaller move\",\"feedback\":\"Quiet bars don't predict more quiet. Volatility tends to drift back to its average, so ranges usually widen again.\"},{\"id\":\"unknown\",\"label\":\"No idea\",\"feedback\":\"For direction, that's honest. For size there is a pattern: ranges tend to widen again after a squeeze.\"}],\"answer\":\"bigger\"},\"compare\":\"You picked {yours}. Contraction tends to be followed by expansion in size, because volatility reverts to its average. The direction stays unknown.\",\"concept\":\"inside-outside-bars\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"An [[inside-bar]] has its high at or below the previous high and its low at or above the previous low. Two in a row make **ii**, three make **iii**. An [[outside-bar]] goes beyond both ends of the previous bar. An [[nr7|NR7]] bar has the narrowest range of the last seven bars.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100.2,\"h\":100.9,\"l\":99.9,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.2,\"c\":100.4},{\"o\":100.4,\"h\":101,\"l\":100.1,\"c\":100.95}],\"visible\":2},\"steps\":[{\"text\":\"Bar 2 stays inside bar 1: high 100.80 under 100.90, low 100.20 above 99.90.\",\"layers\":[{\"kind\":\"zone\",\"from\":99.9,\"to\":100.9,\"role\":\"neutral\",\"label\":\"BAR 1 RANGE\"}]},{\"text\":\"Bar 3 goes beyond bar 2 at both ends, 101.00 and 100.10: an outside bar.\",\"visible\":3,\"layers\":[{\"kind\":\"marker\",\"index\":2,\"at\":\"high\",\"label\":\"101.00\",\"role\":\"concept\"},{\"kind\":\"marker\",\"index\":2,\"at\":\"low\",\"label\":\"100.10\",\"role\":\"concept\"}]}]}},{\"kind\":\"hotspot\",\"title\":\"Find the outside bar\",\"prompt\":\"Tap the outside bar.\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.5,\"l\":99.8,\"c\":100.4},{\"o\":100.4,\"h\":100.9,\"l\":100.3,\"c\":100.8},{\"o\":100.8,\"h\":101.1,\"l\":100.5,\"c\":100.6},{\"o\":100.6,\"h\":101,\"l\":100.55,\"c\":100.9},{\"o\":100.9,\"h\":101.3,\"l\":100.4,\"c\":101.2},{\"o\":101.2,\"h\":101.6,\"l\":101.1,\"c\":101.5},{\"o\":101.5,\"h\":101.7,\"l\":101.2,\"c\":101.3},{\"o\":101.3,\"h\":101.55,\"l\":101,\"c\":101.1},{\"o\":101.1,\"h\":101.4,\"l\":100.92,\"c\":101.35},{\"o\":101.35,\"h\":101.55,\"l\":101.05,\"c\":101.45},{\"o\":101.45,\"h\":101.6,\"l\":101.3,\"c\":101.4},{\"o\":101.4,\"h\":101.9,\"l\":101.35,\"c\":101.85}]},\"zones\":[{\"id\":\"b4\",\"label\":\"Bar 4\",\"index\":3,\"feedback\":\"Bar 4 is an inside bar: its high, 101.00, and low, 100.55, stay within bar 3's 101.10 and 100.50.\"},{\"id\":\"b5\",\"label\":\"Bar 5\",\"index\":4},{\"id\":\"b8\",\"label\":\"Bar 8\",\"index\":7,\"feedback\":\"Bar 8's low, 101.00, is under bar 7's, but its high, 101.55, isn't above bar 7's 101.70. An outside bar needs both.\"},{\"id\":\"b11\",\"label\":\"Bar 11\",\"index\":10,\"feedback\":\"Bar 11 is the narrow one, a range of 0.30. An outside bar reaches beyond the bar before at both ends.\"}],\"answer\":\"b5\",\"correct\":\"Bar 5: high 101.30 above bar 4's 101.00, low 100.40 below its 100.55. It covers bar 4's whole range and more.\",\"concept\":\"inside-outside-bars\"},{\"kind\":\"hotspot\",\"title\":\"Find the NR7\",\"prompt\":\"Now tap the NR7 bar: the narrowest range of the last seven bars.\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.5,\"l\":99.8,\"c\":100.4},{\"o\":100.4,\"h\":100.9,\"l\":100.3,\"c\":100.8},{\"o\":100.8,\"h\":101.1,\"l\":100.5,\"c\":100.6},{\"o\":100.6,\"h\":101,\"l\":100.55,\"c\":100.9},{\"o\":100.9,\"h\":101.3,\"l\":100.4,\"c\":101.2},{\"o\":101.2,\"h\":101.6,\"l\":101.1,\"c\":101.5},{\"o\":101.5,\"h\":101.7,\"l\":101.2,\"c\":101.3},{\"o\":101.3,\"h\":101.55,\"l\":101,\"c\":101.1},{\"o\":101.1,\"h\":101.4,\"l\":100.92,\"c\":101.35},{\"o\":101.35,\"h\":101.55,\"l\":101.05,\"c\":101.45},{\"o\":101.45,\"h\":101.6,\"l\":101.3,\"c\":101.4},{\"o\":101.4,\"h\":101.9,\"l\":101.35,\"c\":101.85}]},\"zones\":[{\"id\":\"b4\",\"label\":\"Bar 4\",\"index\":3,\"feedback\":\"Bar 4's range, 0.45, is narrow, but there aren't six bars before it to compare with.\"},{\"id\":\"b9\",\"label\":\"Bar 9\",\"index\":8,\"feedback\":\"Bar 9's range is 0.48, but bar 4's 0.45 is within its last seven, so bar 9 isn't the narrowest.\"},{\"id\":\"b10\",\"label\":\"Bar 10\",\"index\":9,\"feedback\":\"Bar 10's range is 0.50, the same as bars 6 and 7. NR7 has to be narrower than all six before it.\"},{\"id\":\"b11\",\"label\":\"Bar 11\",\"index\":10}],\"answer\":\"b11\",\"correct\":\"Bar 11: a range of 0.30, under each of the six before it (0.90, 0.50, 0.50, 0.55, 0.48, 0.50). It isn't an inside bar: its high, 101.60, tops bar 10's.\",\"concept\":\"inside-outside-bars\"},{\"kind\":\"figure\",\"title\":\"Bracketing the ii\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100.1,\"h\":100.4,\"l\":99.9,\"c\":100.3},{\"o\":100.3,\"h\":100.55,\"l\":100.05,\"c\":100.15},{\"o\":100.15,\"h\":100.35,\"l\":99.75,\"c\":99.9},{\"o\":99.9,\"h\":101,\"l\":99.8,\"c\":100.8},{\"o\":100.8,\"h\":100.8,\"l\":100,\"c\":100.2},{\"o\":100.2,\"h\":100.7,\"l\":100.1,\"c\":100.55}]},\"steps\":[{\"text\":\"ii: bar 5 sits inside bar 4, and bar 6 inside bar 5.\",\"layers\":[{\"kind\":\"zone\",\"from\":100.1,\"to\":100.7,\"role\":\"neutral\",\"label\":\"BAR 6 RANGE\"}]},{\"text\":\"Buy stop one tick above bar 6, 100.71. Sell stop one tick below, 100.09.\",\"layers\":[{\"kind\":\"level\",\"price\":100.71,\"role\":\"entry\",\"label\":\"BUY STOP · SHORT'S STOP 100.71\"},{\"kind\":\"level\",\"price\":100.09,\"role\":\"entry\",\"label\":\"SELL STOP · LONG'S STOP 100.09\"}]},{\"text\":\"Each leg's stop is the other entry: 0.62 of risk either way.\"}]},\"text\":\"That's an [[oco-order|OCO]] pair: whichever side breaks first fills, and the other entry is cancelled. Size it from the larger of the two distances; here both are 0.62.\",\"concept\":\"oco-order\"},{\"kind\":\"reveal\",\"title\":\"A break that fails\",\"prompt\":\"Bar 5 is an inside bar: high 100.85, low 100.35. Bar 6 broke below it and closed at 100.20. Reveal the next three bars.\",\"chart\":{\"candles\":[{\"o\":100.8,\"h\":101.1,\"l\":100.6,\"c\":101},{\"o\":101,\"h\":101.2,\"l\":100.7,\"c\":100.8},{\"o\":100.8,\"h\":100.95,\"l\":100.4,\"c\":100.5},{\"o\":100.5,\"h\":100.9,\"l\":100.3,\"c\":100.85},{\"o\":100.85,\"h\":100.85,\"l\":100.35,\"c\":100.45},{\"o\":100.45,\"h\":100.5,\"l\":100.1,\"c\":100.2},{\"o\":100.2,\"h\":100.6,\"l\":100.15,\"c\":100.55},{\"o\":100.55,\"h\":101,\"l\":100.5,\"c\":100.95},{\"o\":100.95,\"h\":101.25,\"l\":100.9,\"c\":101.2}],\"visible\":6,\"layers\":[{\"kind\":\"zone\",\"from\":100.35,\"to\":100.85,\"role\":\"neutral\",\"label\":\"INSIDE BAR\"}]},\"choices\":[{\"id\":\"falls\",\"label\":\"The fall continues\"},{\"id\":\"back\",\"label\":\"Price closes back above 100.85\"}],\"after\":\"Bar 8 closed at 100.95, above the inside bar's high: a [[hikkake]]. The break below trapped sellers: a short from 100.34 with its stop at 100.86 was stopped out on bar 8, which reached 101.00. Hikkake traders buy that second break. The setup has no published statistics.\",\"concept\":\"inside-outside-bars\"},{\"kind\":\"match\",\"title\":\"Inside bar or harami?\",\"prompt\":\"An inside bar compares ranges; a harami (unit 2.1) compares bodies. Sort each pair of bars.\",\"pairs\":[{\"left\":\"Bar 2's high and low are inside bar 1's, and its body is inside bar 1's body\",\"right\":\"Both\",\"wrong\":\"Range inside range and body inside body: it's both at once.\"},{\"left\":\"Bar 2's body is inside bar 1's body, but its upper wick pokes above bar 1's high\",\"right\":\"Harami only\",\"wrong\":\"The bodies nest, so it's a harami. The wick above bar 1's high stops it being an inside bar.\"},{\"left\":\"Bar 2's range is inside bar 1's, but bar 1 is a doji and bar 2's body is larger than its body\",\"right\":\"Inside bar only\",\"wrong\":\"The range nests, so it's an inside bar. A body bigger than bar 1's tiny body can't be a harami.\"},{\"left\":\"Bar 2's high is above bar 1's high and its low is below bar 1's low\",\"right\":\"Neither\",\"wrong\":\"That's an outside bar: bigger at both ends. Neither inside bar nor harami.\"}],\"correct\":\"Inside bars compare ranges, harami compares bodies. They often coincide, but not always.\",\"concept\":\"inside-outside-bars\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"The definitions are mechanical. The setups built on them, OCO breakouts and hikkakes, are heuristics with no published statistics. What has support is size, not direction: quiet stretches tend to be followed by wider ranges, because [[volatility]] reverts toward its average.\"}],\"task\":{\"widget\":\"position-size\",\"goal\":\"OCO on the ii: buy stop 100.71, sell stop 100.09, each stopped at the other. Size it so a stop-out loses at most 100.00 (0.5% of 20,000.00), costs included.\",\"start\":{\"account\":20000,\"riskPct\":0.5,\"entry\":100.71,\"stop\":100.09,\"units\":161},\"locked\":[\"account\",\"riskPct\",\"entry\",\"stop\"],\"hidden\":[\"simpleQty\",\"qty\"],\"success\":{\"all\":[{\"field\":\"units\",\"eq\":138},{\"field\":\"entry\",\"eq\":100.71},{\"field\":\"stop\",\"eq\":100.09}]},\"feedback\":[{\"when\":{\"field\":\"units\",\"eq\":161},\"text\":\"161 is the textbook size, 100.00 ÷ 0.62, before costs. The two commissions add about 0.10 a unit: 115.99 at the stop.\"},{\"when\":{\"field\":\"units\",\"eq\":139},\"text\":\"139 units lose 100.14 with both commissions, just over 100.00.\"},{\"when\":{\"field\":\"units\",\"gt\":139},\"text\":\"{units} units would lose {lossAtStop:2} at the stop, over 100.00.\"},{\"when\":{\"field\":\"units\",\"lt\":138},\"text\":\"{units} units fit, losing {lossAtStop:2}. One more unit would still fit: find the most that does.\"}],\"correct\":\"138 units lose 99.42 at the stop: 0.62 a unit plus about 0.10 of commission. The short leg has the same distance, so the same size fits it. Stop entries can slip, so the real loss can be larger.\",\"hints\":[\"The cost per unit at the stop is 0.62 plus 0.05% of 100.71 and 0.05% of 100.09.\",\"0.62 + 0.0005 × (100.71 + 100.09) = 0.7204 a unit. Divide 100.00 by it.\",\"100.00 ÷ 0.7204 = 138.8. Round down.\"],\"showMe\":{\"units\":138},\"concept\":\"inside-outside-bars\"},\"check\":[\"q-2.6.3-1\",\"q-2.6.3-2\",\"q-2.6.3-3\"],\"recap\":{\"takeaways\":[\"Inside bar: range within the last bar's. Outside bar: beyond both ends. NR7: narrowest of seven.\",\"Bracket an inside bar with OCO stop entries, each stopped at the other side; size from the larger distance.\",\"Hikkake: an inside bar, a false break one way, then a close beyond the other side.\"],\"next\":\"Next, 2.6.4: pullbacks in two legs, and counting H1 and H2 to time the second entry.\"}},\"2.6.4\":{\"unit\":\"2.6\",\"courseId\":\"2.6.4\",\"bridge\":\"In 1.5.3 a pullback was a fall inside an uptrend, and in 2.6.2 you entered one tick beyond a signal bar. Here you count the pullback's bars, H1 and H2, and place that same stop entry on the second leg.\",\"hook\":{\"prompt\":\"During this pullback in an uptrend, tap the first bar whose high goes above the previous bar's high.\",\"control\":{\"kind\":\"tap\",\"chart\":{\"candles\":[{\"o\":102.4,\"h\":102.75,\"l\":102.35,\"c\":102.7},{\"o\":102.7,\"h\":103.05,\"l\":102.55,\"c\":102.95},{\"o\":102.95,\"h\":103.1,\"l\":102.7,\"c\":102.8},{\"o\":102.8,\"h\":103.4,\"l\":102.75,\"c\":103.35},{\"o\":103.35,\"h\":103.9,\"l\":103.3,\"c\":103.85},{\"o\":103.85,\"h\":104.55,\"l\":103.8,\"c\":104.5},{\"o\":104.5,\"h\":105,\"l\":104.4,\"c\":104.6},{\"o\":104.6,\"h\":104.6,\"l\":104.1,\"c\":104.2},{\"o\":104.2,\"h\":104.3,\"l\":103.9,\"c\":104.05},{\"o\":104.05,\"h\":104.5,\"l\":104,\"c\":104.15},{\"o\":104.15,\"h\":104.2,\"l\":103.85,\"c\":103.88},{\"o\":103.88,\"h\":104,\"l\":103.7,\"c\":103.97},{\"o\":103.97,\"h\":104.35,\"l\":103.95,\"c\":104.3}],\"layers\":[{\"kind\":\"marker\",\"index\":6,\"at\":\"high\",\"label\":\"HIGH 105.00\",\"role\":\"concept\"}]},\"zones\":[{\"id\":\"b8\",\"label\":\"Bar 8\",\"index\":7,\"feedback\":\"Bar 8's high, 104.60, is under bar 7's 105.00.\"},{\"id\":\"b9\",\"label\":\"Bar 9\",\"index\":8,\"feedback\":\"Bar 9's high, 104.30, is under bar 8's 104.60.\"},{\"id\":\"b10\",\"label\":\"Bar 10\",\"index\":9},{\"id\":\"b11\",\"label\":\"Bar 11\",\"index\":10,\"feedback\":\"Bar 11's high, 104.20, is under bar 10's 104.50. Look one bar earlier.\"},{\"id\":\"b12\",\"label\":\"Bar 12\",\"index\":11,\"feedback\":\"Bar 12's high, 104.00, is under bar 11's.\"},{\"id\":\"b13\",\"label\":\"Bar 13\",\"index\":12,\"feedback\":\"Bar 13 does beat the bar before, but it isn't the first to do so.\"}],\"answer\":\"b10\"},\"compare\":\"You tapped {yours}. Bar 10's high, 104.50, was the first above the bar before, 104.30: H1, the first attempt to resume the uptrend.\",\"concept\":\"bar-counting\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"Count bars, not swings. In a bull [[pullback]], **H1** is the first bar whose high beats the previous bar's high: the first attempt to resume the trend. If the pullback then makes a lower low, the next such bar is **H2**. Bear trends mirror [[high-1-high-2|H1 and H2]] as L1 and L2. A new trend extreme resets the count.\"},{\"kind\":\"figure\",\"title\":\"Two legs, two attempts\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":102.4,\"h\":102.75,\"l\":102.35,\"c\":102.7},{\"o\":102.7,\"h\":103.05,\"l\":102.55,\"c\":102.95},{\"o\":102.95,\"h\":103.1,\"l\":102.7,\"c\":102.8},{\"o\":102.8,\"h\":103.4,\"l\":102.75,\"c\":103.35},{\"o\":103.35,\"h\":103.9,\"l\":103.3,\"c\":103.85},{\"o\":103.85,\"h\":104.55,\"l\":103.8,\"c\":104.5},{\"o\":104.5,\"h\":105,\"l\":104.4,\"c\":104.6},{\"o\":104.6,\"h\":104.6,\"l\":104.1,\"c\":104.2},{\"o\":104.2,\"h\":104.3,\"l\":103.9,\"c\":104.05},{\"o\":104.05,\"h\":104.5,\"l\":104,\"c\":104.15},{\"o\":104.15,\"h\":104.2,\"l\":103.85,\"c\":103.88},{\"o\":103.88,\"h\":104,\"l\":103.7,\"c\":103.97},{\"o\":103.97,\"h\":104.35,\"l\":103.95,\"c\":104.3}]},\"steps\":[{\"text\":\"Leg A: from the 105.00 high down to 103.90 in two bars.\",\"layers\":[{\"kind\":\"path\",\"role\":\"down\",\"label\":\"LEG A\",\"points\":[{\"index\":6,\"price\":105},{\"index\":8,\"price\":103.9}]}]},{\"text\":\"Bar 10's high, 104.50, beats bar 9's 104.30: H1. The bounce stalls.\",\"layers\":[{\"kind\":\"marker\",\"index\":9,\"at\":\"high\",\"label\":\"H1\",\"role\":\"concept\"}]},{\"text\":\"Leg C: bars 11 and 12 fall to a lower pullback low, 103.70.\",\"layers\":[{\"kind\":\"path\",\"role\":\"down\",\"label\":\"LEG C\",\"points\":[{\"index\":9,\"price\":104.5},{\"index\":11,\"price\":103.7}]},{\"kind\":\"marker\",\"index\":11,\"at\":\"low\",\"label\":\"103.70\",\"role\":\"concept\"}]},{\"text\":\"Bar 13's high, 104.35, beats bar 12's 104.00: H2, the second entry.\",\"layers\":[{\"kind\":\"marker\",\"index\":12,\"at\":\"high\",\"label\":\"H2\",\"role\":\"up\"}]}]},\"text\":\"That's a [[two-legged-pullback]]: leg A down, a small bounce, then leg C to a lower low.\",\"concept\":\"two-legged-pullback\"},{\"kind\":\"hotspot\",\"title\":\"The mirror: L1 and L2\",\"prompt\":\"A bear trend made its low at 96.80, then rallied in two legs. Tap L2.\",\"chart\":{\"candles\":[{\"o\":98.6,\"h\":98.65,\"l\":98.25,\"c\":98.3},{\"o\":98.3,\"h\":98.45,\"l\":97.95,\"c\":98.05},{\"o\":98.05,\"h\":98.2,\"l\":97.65,\"c\":97.7},{\"o\":97.7,\"h\":97.75,\"l\":97.2,\"c\":97.25},{\"o\":97.25,\"h\":97.35,\"l\":96.8,\"c\":97.15},{\"o\":97.15,\"h\":97.45,\"l\":97.05,\"c\":97.4},{\"o\":97.4,\"h\":97.7,\"l\":97.3,\"c\":97.6},{\"o\":97.6,\"h\":97.65,\"l\":97.2,\"c\":97.35},{\"o\":97.35,\"h\":97.85,\"l\":97.3,\"c\":97.8},{\"o\":97.8,\"h\":97.95,\"l\":97.6,\"c\":97.63},{\"o\":97.63,\"h\":97.68,\"l\":97.25,\"c\":97.3}],\"layers\":[{\"kind\":\"marker\",\"index\":4,\"at\":\"low\",\"label\":\"LOW 96.80\",\"role\":\"concept\"}]},\"zones\":[{\"id\":\"a8\",\"label\":\"Bar 8\",\"index\":7,\"feedback\":\"Bar 8 is L1: its low, 97.20, was the first under the bar before. L2 comes after the rally's next leg up.\"},{\"id\":\"a9\",\"label\":\"Bar 9\",\"index\":8,\"feedback\":\"Bar 9's low, 97.30, stayed above bar 8's 97.20. It's the second leg up, not a count.\"},{\"id\":\"a10\",\"label\":\"Bar 10\",\"index\":9,\"feedback\":\"Bar 10 made the new rally high, 97.95. It's the signal bar; the next bar to dip under its low is L2.\"},{\"id\":\"a11\",\"label\":\"Bar 11\",\"index\":10}],\"answer\":\"a11\",\"correct\":\"Bar 11: its low, 97.25, went under bar 10's 97.60, after the rally's second leg. That's L2, the second attempt down.\",\"concept\":\"bar-counting\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"In Brooks' reading, the first attempt to resume a trend often fails, so H2 is his preferred entry. In a strong trend, H1 can work. A third or fourth attempt suggests the trend is turning into a range. These are heuristics with no published statistics: [[evidence-grade]] D.\"},{\"kind\":\"explain\",\"title\":\"Why the second attempt can trap\",\"text\":\"Traders who sold the failed H1 read leg C as a reversal. Their protective stops sit above the pullback's highs. When H2 trades above the signal bar, those buy stops add to the move: a [[second-entry]] can trap them. In a [[range]] there's no trend to resume, so counts happen everywhere and mean little.\"},{\"kind\":\"predict\",\"prompt\":\"LABX has ranged between 98.00 and 100.00 for two days. An H2 forms at 99.00, mid-range. How much does the count tell you?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"lot\",\"label\":\"A lot: H2 is the preferred entry\",\"feedback\":\"H2 is a trend tool: a second attempt to resume a trend. Mid-range, there's no trend to resume.\"},{\"id\":\"little\",\"label\":\"Little: in a range, counts appear all the time\",\"feedback\":\"Right.\"},{\"id\":\"breakout\",\"label\":\"It signals a breakout above 100.00\",\"feedback\":\"A count says nothing about a breakout. Mid-range bars go both ways.\"}],\"answer\":\"little\"},\"reveal\":\"Counting needs a trend first: higher highs and higher lows. A count is only a bar beating the previous high, and random data produces those too. That's why the trend check comes before the count.\",\"concept\":\"bar-counting\"},{\"kind\":\"worked\",\"title\":\"The H2 order\",\"lines\":[\"Signal bar: bar 12, high 104.00, low 103.70, the pullback's low.\",\"The protective stop goes one tick under the pullback low: 103.69.\",\"The entry is a buy stop one tick above the signal bar's high.\",\"Buy stop = ?\"],\"ask\":{\"answer\":104.01,\"tolerance\":0,\"feedback\":[{\"value\":104.35,\"text\":\"That's bar 13's high, the H2 bar itself. The order is placed before it, above the signal bar: 104.00 + 0.01.\"},{\"value\":104,\"text\":\"One tick above the high, so a mere touch of 104.00 doesn't fill you: 104.01.\"}],\"correct\":\"Right: 104.01. Bar 13 traded through it, so bar 13 is both the H2 and the entry bar.\"},\"after\":\"Buy stop 104.01, stop 103.69: 0.32 of risk a unit. Had bar 13 never traded above 104.00, there would be no trade.\",\"concept\":\"signal-and-entry-bars\"}],\"task\":{\"widget\":\"bracket-builder\",\"data\":{\"chart\":{\"candles\":[{\"o\":102.4,\"h\":102.75,\"l\":102.35,\"c\":102.7},{\"o\":102.7,\"h\":103.05,\"l\":102.55,\"c\":102.95},{\"o\":102.95,\"h\":103.1,\"l\":102.7,\"c\":102.8},{\"o\":102.8,\"h\":103.4,\"l\":102.75,\"c\":103.35},{\"o\":103.35,\"h\":103.9,\"l\":103.3,\"c\":103.85},{\"o\":103.85,\"h\":104.55,\"l\":103.8,\"c\":104.5},{\"o\":104.5,\"h\":105,\"l\":104.4,\"c\":104.6},{\"o\":104.6,\"h\":104.6,\"l\":104.1,\"c\":104.2},{\"o\":104.2,\"h\":104.3,\"l\":103.9,\"c\":104.05},{\"o\":104.05,\"h\":104.5,\"l\":104,\"c\":104.15},{\"o\":104.15,\"h\":104.2,\"l\":103.85,\"c\":103.88},{\"o\":103.88,\"h\":104,\"l\":103.7,\"c\":103.97},{\"o\":103.97,\"h\":104.35,\"l\":103.95,\"c\":104.3}],\"layers\":[{\"kind\":\"marker\",\"index\":9,\"at\":\"high\",\"label\":\"H1\",\"role\":\"concept\"},{\"kind\":\"marker\",\"index\":12,\"at\":\"high\",\"label\":\"H2\",\"role\":\"concept\"},{\"kind\":\"marker\",\"index\":11,\"at\":\"low\",\"label\":\"103.70\",\"role\":\"concept\"}]},\"entry\":104.01,\"units\":100},\"goal\":\"Entry: the H2 buy stop at 104.01. Drag the stop one tick under the pullback low, and the target to the trend high, 105.00. Then read the reward-to-risk.\",\"start\":{\"stop\":103.8,\"target\":104.5,\"units\":100},\"locked\":[\"units\"],\"success\":{\"all\":[{\"field\":\"stop\",\"eq\":103.69},{\"field\":\"target\",\"eq\":105}]},\"feedback\":[{\"when\":{\"field\":\"stop\",\"eq\":103.7},\"text\":\"That's the pullback low itself. One tick under it: 103.69.\"},{\"when\":{\"field\":\"stop\",\"gt\":103.7},\"text\":\"At {stop:2} the stop sits above the pullback low, 103.70. The H2 idea fails only if price makes a new pullback low.\"},{\"when\":{\"field\":\"stop\",\"lt\":103.69},\"text\":\"At {stop:2} you risk {stopDistance:2} a unit. The invalidation is the pullback low: one tick under 103.70.\"},{\"when\":{\"field\":\"target\",\"ne\":105},\"text\":\"Stop right. The target is a test of the trend high, 105.00. You're at {target:2}.\"}],\"correct\":\"Risk 0.32, reward 0.99: about 3.1R if the high is tested. A test of the prior high is a common first target, not a promise.\",\"hints\":[\"The pullback low is 103.70, on bar 12.\",\"Stop at 103.69. The trend high is bar 7's, 105.00.\",\"Stop 103.69, target 105.00.\"],\"showMe\":{\"stop\":103.69,\"target\":105},\"concept\":\"bar-counting\"},\"check\":[\"q-2.6.4-1\",\"q-2.6.4-2\",\"q-2.6.4-3\"],\"recap\":{\"takeaways\":[\"H1: the first bar above the previous high in a bull pullback. H2: the next one, after a lower low.\",\"H2 entry: buy stop one tick above the signal bar; stop one tick under the pullback low.\",\"A second entry can trap counter-trend traders. In a range, counts appear everywhere and mean little.\"],\"next\":\"Next, 2.6.5: channels and wedges bar by bar, where the size of the pullbacks grades the trend.\"}},\"2.6.5\":{\"unit\":\"2.6\",\"courseId\":\"2.6.5\",\"bridge\":\"In 2.2.1 you drew channels and in 2.2.8 wedges, as whole patterns; in 2.6.4 you counted a pullback's legs. Here you grade a trend by its pullbacks, tight, broad or micro, and count three pushes into a wedge, bar by bar.\",\"hook\":{\"prompt\":\"For 8 bars in a row, no bar's low went below the previous bar's low. Is this uptrend strong or weak?\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.3,\"l\":99.9,\"c\":100.25},{\"o\":100.25,\"h\":100.5,\"l\":100.1,\"c\":100.45},{\"o\":100.45,\"h\":100.7,\"l\":100.3,\"c\":100.6},{\"o\":100.6,\"h\":100.85,\"l\":100.45,\"c\":100.8},{\"o\":100.8,\"h\":100.95,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":101.1,\"l\":100.65,\"c\":101.05},{\"o\":101.05,\"h\":101.3,\"l\":100.9,\"c\":101.25},{\"o\":101.25,\"h\":101.45,\"l\":101.1,\"c\":101.35},{\"o\":101.35,\"h\":101.7,\"l\":101.3,\"c\":101.65}]},\"steps\":[{\"text\":\"From bar 2 to bar 9, every low is at or above the low before it.\"}]},\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"strong\",\"label\":\"Strong\",\"feedback\":\"That's Brooks' reading: sellers couldn't take out a single prior low.\"},{\"id\":\"weak\",\"label\":\"Weak\",\"feedback\":\"Weak trends have deep, overlapping pullbacks. Here no bar even dipped under the bar before.\"},{\"id\":\"unclear\",\"label\":\"Can't tell\",\"feedback\":\"The rule is measurable: eight bars without a lower low is a micro channel, a strong reading.\"}],\"answer\":\"strong\"},\"compare\":\"You picked {yours}. Eight bars without a lower low is a micro channel: sellers never took out a prior bar's low. Brooks reads that as strong.\",\"concept\":\"price-channels\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"Al Brooks grades channels by their pullbacks. **Tight**: pullbacks of at most 1 ATR and 3 bars. **Broad**: pullbacks give back more than half of the leg before, close to a range. [[micro-channel|Micro]]: five or more bars in a row with no low below the previous low, or no high above it in a bear trend.\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.3,\"l\":99.9,\"c\":100.25},{\"o\":100.25,\"h\":100.5,\"l\":100.1,\"c\":100.45},{\"o\":100.45,\"h\":100.7,\"l\":100.3,\"c\":100.6},{\"o\":100.6,\"h\":100.85,\"l\":100.45,\"c\":100.8},{\"o\":100.8,\"h\":100.95,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":101.1,\"l\":100.65,\"c\":101.05},{\"o\":101.05,\"h\":101.3,\"l\":100.9,\"c\":101.25},{\"o\":101.25,\"h\":101.45,\"l\":101.1,\"c\":101.35},{\"o\":101.35,\"h\":101.7,\"l\":101.3,\"c\":101.65},{\"o\":101.65,\"h\":101.75,\"l\":101.2,\"c\":101.3}],\"visible\":9},\"steps\":[{\"text\":\"Bars 2 to 9: no low below the previous bar's low. A micro channel.\",\"layers\":[{\"kind\":\"path\",\"role\":\"up\",\"label\":\"LOWS\",\"points\":[{\"index\":0,\"price\":99.9},{\"index\":1,\"price\":100.1},{\"index\":2,\"price\":100.3},{\"index\":3,\"price\":100.45},{\"index\":4,\"price\":100.6},{\"index\":5,\"price\":100.65},{\"index\":6,\"price\":100.9},{\"index\":7,\"price\":101.1},{\"index\":8,\"price\":101.3}]}]},{\"text\":\"Bar 10 dips to 101.20, under bar 9's 101.30: the micro channel ends.\",\"visible\":10,\"layers\":[{\"kind\":\"marker\",\"index\":9,\"at\":\"low\",\"label\":\"LOWER LOW\",\"role\":\"down\"}]}]}},{\"kind\":\"match\",\"prompt\":\"Match each description to its channel.\",\"columns\":[\"Description\",\"Channel\"],\"pairs\":[{\"left\":\"Seven bars in a row, each low at or above the one before\",\"right\":\"Micro channel\",\"wrong\":\"No lower low bar after bar is the micro channel's signature.\"},{\"left\":\"Pullbacks of one or two bars, each smaller than 1 ATR\",\"right\":\"Tight channel\",\"wrong\":\"Small, short pullbacks: the trend barely pauses. That's tight, not broad.\"},{\"left\":\"Each pullback gives back more than half of the leg before it\",\"right\":\"Broad channel\",\"wrong\":\"Deep pullbacks make a broad channel, close to a range.\"}],\"correct\":\"Pullback size and length grade the trend: micro and tight are strong, broad is weak.\",\"concept\":\"price-channels\"},{\"kind\":\"predict\",\"title\":\"Three pushes\",\"prompt\":\"Three pushes up, each to a slightly higher high. Tap the push with the shortest leg: the weakest momentum.\",\"control\":{\"kind\":\"tap\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.2,\"l\":99.8,\"c\":100.1},{\"o\":100.1,\"h\":100.6,\"l\":100.05,\"c\":100.55},{\"o\":100.55,\"h\":101,\"l\":100.5,\"c\":100.95},{\"o\":100.95,\"h\":100.98,\"l\":100.6,\"c\":100.65},{\"o\":100.65,\"h\":100.7,\"l\":100.4,\"c\":100.5},{\"o\":100.5,\"h\":100.9,\"l\":100.45,\"c\":100.85},{\"o\":100.85,\"h\":101.2,\"l\":100.8,\"c\":101.15},{\"o\":101.15,\"h\":101.18,\"l\":100.85,\"c\":100.9},{\"o\":100.9,\"h\":100.95,\"l\":100.75,\"c\":100.85},{\"o\":100.85,\"h\":101.1,\"l\":100.8,\"c\":101.05},{\"o\":101.05,\"h\":101.25,\"l\":100.95,\"c\":101.1},{\"o\":101.1,\"h\":101.15,\"l\":100.7,\"c\":100.75},{\"o\":100.75,\"h\":100.8,\"l\":100.4,\"c\":100.45}]},\"zones\":[{\"id\":\"p1\",\"label\":\"Push 1, 101.00\",\"index\":2,\"price\":101,\"feedback\":\"Push 1 climbed from 99.80 to 101.00: 1.20, the longest leg.\"},{\"id\":\"p2\",\"label\":\"Push 2, 101.20\",\"index\":6,\"price\":101.2,\"feedback\":\"Push 2 climbed 0.80, from 100.40. Shorter than push 1, but not the shortest.\"},{\"id\":\"p3\",\"label\":\"Push 3, 101.25\",\"index\":10,\"price\":101.25,\"feedback\":\"Right.\"}],\"answer\":\"p3\"},\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.2,\"l\":99.8,\"c\":100.1},{\"o\":100.1,\"h\":100.6,\"l\":100.05,\"c\":100.55},{\"o\":100.55,\"h\":101,\"l\":100.5,\"c\":100.95},{\"o\":100.95,\"h\":100.98,\"l\":100.6,\"c\":100.65},{\"o\":100.65,\"h\":100.7,\"l\":100.4,\"c\":100.5},{\"o\":100.5,\"h\":100.9,\"l\":100.45,\"c\":100.85},{\"o\":100.85,\"h\":101.2,\"l\":100.8,\"c\":101.15},{\"o\":101.15,\"h\":101.18,\"l\":100.85,\"c\":100.9},{\"o\":100.9,\"h\":100.95,\"l\":100.75,\"c\":100.85},{\"o\":100.85,\"h\":101.1,\"l\":100.8,\"c\":101.05},{\"o\":101.05,\"h\":101.25,\"l\":100.95,\"c\":101.1},{\"o\":101.1,\"h\":101.15,\"l\":100.7,\"c\":100.75},{\"o\":100.75,\"h\":100.8,\"l\":100.4,\"c\":100.45}]},\"steps\":[{\"text\":\"Push 1: from 99.80 to 101.00, a 1.20 leg.\",\"layers\":[{\"kind\":\"bracket\",\"from\":99.8,\"to\":101,\"index\":2,\"label\":\"1.20\"}]},{\"text\":\"Push 2: from 100.40 to 101.20, a 0.80 leg.\",\"layers\":[{\"kind\":\"bracket\",\"from\":100.4,\"to\":101.2,\"index\":6,\"label\":\"0.80\"}]},{\"text\":\"Push 3: from 100.75 to 101.25, only 0.50. Momentum fades.\",\"layers\":[{\"kind\":\"bracket\",\"from\":100.75,\"to\":101.25,\"index\":10,\"label\":\"0.50\"}]}]},\"reveal\":\"Each push gained less: 1.20, 0.80, 0.50. That's a [[three-push-wedge]]: three pushes with fading momentum, read as a possible reversal. Here the bars after push 3 fell back to 100.40; another time they might not.\",\"concept\":\"three-push-wedge\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Brooks' wedge is a three-push idea; its lines don't need to converge. The classic wedge of unit 2.2 is a converging-lines idea. Bulkowski's statistics describe the classic one. Brooks' version has no published statistics.\"},{\"kind\":\"explain\",\"text\":\"A pullback can push three times against the trend. In a bull trend, three pushes down make a **wedge bull flag**, and its buy setup is an H3, the third attempt up. Another common shape is a [[spike-and-channel]]: a strong breakout, the spike, followed by a slower channel in the same direction.\"},{\"kind\":\"reveal\",\"title\":\"Draw it now\",\"prompt\":\"You draw the lower channel line now, through the two swing lows so far: 100.20 and 100.70. A touch is a low within 0.05 of the line, closing above it. Reveal 9 more bars. How many touches count?\",\"chart\":{\"candles\":[{\"o\":100.1,\"h\":100.4,\"l\":100.05,\"c\":100.35},{\"o\":100.35,\"h\":100.65,\"l\":100.3,\"c\":100.6},{\"o\":100.6,\"h\":100.75,\"l\":100.4,\"c\":100.45},{\"o\":100.45,\"h\":100.55,\"l\":100.2,\"c\":100.5},{\"o\":100.5,\"h\":100.95,\"l\":100.45,\"c\":100.9},{\"o\":100.9,\"h\":101.25,\"l\":100.85,\"c\":101.2},{\"o\":101.2,\"h\":101.35,\"l\":101,\"c\":101.05},{\"o\":101.05,\"h\":101.1,\"l\":100.8,\"c\":100.85},{\"o\":100.85,\"h\":101,\"l\":100.7,\"c\":100.95},{\"o\":100.95,\"h\":101.4,\"l\":100.9,\"c\":101.35},{\"o\":101.35,\"h\":101.7,\"l\":101.3,\"c\":101.65},{\"o\":101.65,\"h\":101.85,\"l\":101.5,\"c\":101.55},{\"o\":101.55,\"h\":101.6,\"l\":101.25,\"c\":101.3},{\"o\":101.3,\"h\":101.5,\"l\":101.22,\"c\":101.45},{\"o\":101.45,\"h\":101.8,\"l\":101.42,\"c\":101.75},{\"o\":101.75,\"h\":102,\"l\":101.7,\"c\":101.9},{\"o\":101.9,\"h\":101.95,\"l\":101.6,\"c\":101.65},{\"o\":101.65,\"h\":101.7,\"l\":101.45,\"c\":101.5},{\"o\":101.5,\"h\":101.55,\"l\":101.2,\"c\":101.25},{\"o\":101.25,\"h\":101.4,\"l\":101.1,\"c\":101.35}],\"visible\":11,\"layers\":[{\"kind\":\"line\",\"values\":[99.9,100,100.1,100.2,100.3,100.4,100.5,100.6,100.7,100.8,100.9,101,101.1,101.2,101.3,101.4,101.5,101.6,101.7,101.8],\"role\":\"accent\",\"label\":\"YOUR LINE\"},{\"kind\":\"marker\",\"index\":3,\"at\":\"low\",\"label\":\"100.20\",\"role\":\"concept\"},{\"kind\":\"marker\",\"index\":8,\"at\":\"low\",\"label\":\"100.70\",\"role\":\"concept\"}]},\"choices\":[{\"id\":\"none\",\"label\":\"None\",\"feedback\":\"Bar 14's low, 101.22, came within 0.02 of the line, at 101.20 there, and the bar closed above it. That counts.\"},{\"id\":\"one\",\"label\":\"One\",\"feedback\":\"Right.\"},{\"id\":\"three\",\"label\":\"Three\",\"feedback\":\"The two anchors don't count: you drew the line through them. Only touches after you drew it are evidence.\"}],\"answer\":\"one\",\"after\":\"One touch: bar 14 dipped to 101.22, 0.02 from the line, and closed above it. Bar 18 closed at 101.50, under the line at 101.60: the channel broke. Drawn afterwards, the same line shows three touches, but two of them were the anchors you chose.\",\"concept\":\"price-channels\"},{\"kind\":\"predict\",\"title\":\"Name the channel\",\"prompt\":\"Measure its pullbacks: 101.35 down to 100.70 after a leg up from 100.20, and 101.85 down to 101.22 after a leg up from 100.70. Which channel is it?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"tight\",\"label\":\"Tight\",\"feedback\":\"Each pullback is 0.65 or 0.63 deep, well over the average bar range of about 0.38. Tight pullbacks stay within 1 ATR.\"},{\"id\":\"broad\",\"label\":\"Broad\",\"feedback\":\"Right.\"},{\"id\":\"micro\",\"label\":\"Micro\",\"feedback\":\"Bars 8–9 and 13–14 make lower lows, so it isn't a micro channel.\"}],\"answer\":\"broad\"},\"reveal\":\"Pullback 1 gave back 0.65 of a 1.15 leg, 57%; pullback 2 gave back 0.63 of 1.15, 55%. Both over half: a broad channel. Broad channels behave more like ranges: two-sided, with deep pullbacks.\",\"concept\":\"price-channels\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"A line drawn after the fact always fits, because you choose the lows it passes through. Count only the touches after you could have drawn it. Channel types and wedges are Brooks' heuristics with no published statistics, and the same shapes can appear in random data.\"}],\"check\":[\"q-2.6.5-1\",\"q-2.6.5-2\",\"q-2.6.5-3\"],\"recap\":{\"takeaways\":[\"Micro: no lower lows for five or more bars. Tight: shallow, short pullbacks. Broad: pullbacks over half the leg.\",\"A three-push wedge has fading pushes; three pushes against the trend make a wedge flag, H3 or L3.\",\"Touches before you drew a line are its anchors, not evidence. Count only the later ones.\"],\"next\":\"Next, 2.6.6: traps and failed breakouts, where the traders who chased a break fuel the move back.\"}},\"2.6.6\":{\"unit\":\"2.6\",\"courseId\":\"2.6.6\",\"bridge\":\"In 2.2.10 a pattern failed on a close back inside, and in 1.5.6 so did a false breakout. Here you find where the trapped traders' stops sit, and decide only at the bar's close: buy, fade or stand aside, with the invalidation written down.\",\"hook\":{\"prompt\":\"Al Brooks estimates what share of attempts to break out of a trading range fail?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":100,\"step\":5,\"unit\":\"%\",\"start\":50,\"answer\":80,\"tolerance\":10,\"feedback\":[{\"from\":0,\"to\":45,\"text\":\"Lower than his figure. Brooks says most range breakouts fail: about 80%, by his estimate.\"},{\"from\":50,\"to\":65,\"text\":\"A bit low. Brooks puts it at about 80%: his estimate, not a measured rate.\"},{\"from\":70,\"to\":90,\"text\":\"Close to his figure, about 80%. It's an estimate, not a published statistic.\"},{\"from\":95,\"to\":100,\"text\":\"Higher than his figure, about 80%. Some breakouts do run.\"}]},\"compare\":\"You said {yours}. Brooks says about 80%: an experienced trader's estimate, not a statistic. Treat it as a reason for caution, not as a rate to trade on.\",\"concept\":\"false-breakout\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"A [[failed-breakout]]: price closes beyond a level, then closes back inside the range within one to three bars. A breakout that holds closes beyond by a meaningful amount, about half an ATR, and the next bar keeps going: follow-through. At the breakout bar's close, the two look the same.\"},{\"kind\":\"figure\",\"title\":\"Who gets trapped\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":99,\"h\":99.4,\"l\":98.85,\"c\":99.3},{\"o\":99.3,\"h\":99.8,\"l\":99.2,\"c\":99.7},{\"o\":99.7,\"h\":99.95,\"l\":99.4,\"c\":99.5},{\"o\":99.5,\"h\":99.6,\"l\":99,\"c\":99.1},{\"o\":99.1,\"h\":99.25,\"l\":98.6,\"c\":98.7},{\"o\":98.7,\"h\":98.9,\"l\":98.05,\"c\":98.2},{\"o\":98.2,\"h\":98.75,\"l\":98.1,\"c\":98.65},{\"o\":98.65,\"h\":99.2,\"l\":98.55,\"c\":99.05},{\"o\":99.05,\"h\":99.55,\"l\":98.95,\"c\":99.4},{\"o\":99.4,\"h\":99.6,\"l\":98.9,\"c\":99},{\"o\":99,\"h\":99.1,\"l\":98.4,\"c\":98.5},{\"o\":98.5,\"h\":98.6,\"l\":98,\"c\":98.15},{\"o\":98.15,\"h\":98.2,\"l\":97.6,\"c\":97.7},{\"o\":97.7,\"h\":98.4,\"l\":97.65,\"c\":98.3},{\"o\":98.3,\"h\":98.8,\"l\":98.2,\"c\":98.7},{\"o\":98.7,\"h\":99.15,\"l\":98.6,\"c\":99.05},{\"o\":99.05,\"h\":99.4,\"l\":98.95,\"c\":99.3}],\"visible\":13,\"layers\":[{\"kind\":\"level\",\"price\":98,\"role\":\"support\",\"label\":\"RANGE LOW 98.00\"}]},\"steps\":[{\"text\":\"Bar 13 closes at 97.70, under the 98.00 range low. Sellers short the breakdown.\"},{\"text\":\"Bar 14 closes at 98.30, back inside: a failed breakdown.\",\"visible\":14},{\"text\":\"The shorts' stops sat above bar 13's high, 98.20. Bar 14 ran through them.\",\"layers\":[{\"kind\":\"zone\",\"from\":98.2,\"to\":98.4,\"role\":\"stop\",\"label\":\"SHORTS' STOPS\"}]},{\"text\":\"A short's stop is a buy order, so their exits add to the rally. Bar 17 closes at 99.30.\",\"visible\":17}]},\"text\":\"[[trapped-trader|Trapped traders]] are caught on the wrong side; their exits can fuel the move against them. The same event has many names: 2B, turtle soup, swing failure, liquidity sweep (units 3.1 and 3.5).\",\"concept\":\"trapped-traders\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"The mechanism has evidence: stop orders cluster just beyond round numbers, and because stops are trend-following orders, price tends to accelerate when it reaches them (Osler, 2001–2005; [[evidence-grade]] B). So a break through stops can continue as easily as it can fail. The 80% figure is a heuristic.\"},{\"kind\":\"predict\",\"title\":\"Before the close\",\"prompt\":\"Bar 15 is still forming: price is 0.40 above the 102.00 range high, with 10 minutes left in the hour. What do you do?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"enter\",\"label\":\"Buy now, before it runs\",\"feedback\":\"Price can still close back inside. Until the close, you don't know whether it's a breakout or a failure.\"},{\"id\":\"wait\",\"label\":\"Wait for the bar to close\",\"feedback\":\"Right.\"},{\"id\":\"fade\",\"label\":\"Sell now: most breakouts fail\",\"feedback\":\"A fade needs a close back inside. Right now price is above the level.\"}],\"answer\":\"wait\"},\"reveal\":\"Decide at the close. A bar that's above the level now can still close inside it, and then the breakout you bought is the failure you should have faded.\",\"concept\":\"false-breakout\"},{\"kind\":\"reveal\",\"title\":\"Breakout 1\",\"prompt\":\"Bar 15 closed at 102.40, above the 102.00 range high. It's your call, at the close: buy the breakout, wait to fade a close back inside, or stand aside?\",\"chart\":{\"candles\":[{\"o\":101,\"h\":101.4,\"l\":100.85,\"c\":101.3},{\"o\":101.3,\"h\":101.75,\"l\":101.2,\"c\":101.65},{\"o\":101.65,\"h\":101.95,\"l\":101.5,\"c\":101.6},{\"o\":101.6,\"h\":101.7,\"l\":101.1,\"c\":101.2},{\"o\":101.2,\"h\":101.3,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.05,\"c\":100.2},{\"o\":100.2,\"h\":100.7,\"l\":100.1,\"c\":100.65},{\"o\":100.65,\"h\":101.2,\"l\":100.55,\"c\":101.1},{\"o\":101.1,\"h\":101.6,\"l\":101,\"c\":101.5},{\"o\":101.5,\"h\":102,\"l\":101.4,\"c\":101.85},{\"o\":101.85,\"h\":101.95,\"l\":101.35,\"c\":101.45},{\"o\":101.45,\"h\":101.55,\"l\":100.95,\"c\":101.1},{\"o\":101.1,\"h\":101.6,\"l\":101,\"c\":101.55},{\"o\":101.55,\"h\":101.95,\"l\":101.45,\"c\":101.9},{\"o\":101.9,\"h\":102.55,\"l\":101.9,\"c\":102.4},{\"o\":102.4,\"h\":102.5,\"l\":101.7,\"c\":101.8},{\"o\":101.8,\"h\":101.85,\"l\":101.3,\"c\":101.4},{\"o\":101.4,\"h\":101.5,\"l\":100.9,\"c\":101},{\"o\":101,\"h\":101.2,\"l\":100.7,\"c\":100.85}],\"visible\":15,\"layers\":[{\"kind\":\"level\",\"price\":102,\"role\":\"resistance\",\"label\":\"RANGE HIGH 102.00\"}]},\"choices\":[{\"id\":\"enter\",\"label\":\"Buy the breakout at 102.45\"},{\"id\":\"fade\",\"label\":\"Wait to fade a close back inside\"},{\"id\":\"aside\",\"label\":\"Stand aside\"}],\"after\":\"Bar 16 closed at 101.80, back inside: a failed breakout. Bought at 102.45: the stop under the breakout bar's low, 101.90, filled on bar 16. Waited to fade: short at 101.75 after that close, stop above the failed high, 102.55. Stood aside: no cost, no trade.\",\"concept\":\"trapped-traders\"},{\"kind\":\"fields\",\"title\":\"Write the invalidation\",\"prompt\":\"For breakout 1, pick where each idea is proven wrong. Then write the fade's invalidation in your own words.\",\"fields\":[{\"id\":\"longStop\",\"label\":\"Breakout long from 102.45: stop\",\"kind\":\"choice\",\"options\":[101.85,102.15,102.35],\"default\":102.35},{\"id\":\"fadeStop\",\"label\":\"Fade short from 101.75: stop\",\"kind\":\"choice\",\"options\":[101.95,102.35,102.56],\"default\":101.95},{\"id\":\"why\",\"label\":\"The fade is wrong if…\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. price trades back above the failed high, 102.55\",\"required\":true}],\"valid\":{\"all\":[{\"field\":\"longStop\",\"eq\":101.85},{\"field\":\"fadeStop\",\"eq\":102.56}]},\"feedback\":[{\"when\":{\"field\":\"longStop\",\"ne\":101.85},\"text\":\"At {longStop:2} the long's stop is still above the 102.00 level. The breakout is wrong once price is back inside: under the breakout bar's low, 101.90.\"},{\"when\":{\"field\":\"fadeStop\",\"ne\":102.56},\"text\":\"At {fadeStop:2} the fade's stop is under the failed high, 102.55. The fade is wrong only if price takes out that high: one tick above it.\"}],\"correct\":\"Both on the right side: the breakout is wrong back inside the range, the fade is wrong above the failed high. Standing aside needs no stop.\",\"concept\":\"invalidation-level\"},{\"kind\":\"reveal\",\"title\":\"Breakout 2\",\"prompt\":\"Same range, another day. Bar 15 closed at 102.55, above 102.00. At the close: buy the breakout, wait to fade, or stand aside?\",\"chart\":{\"candles\":[{\"o\":101,\"h\":101.4,\"l\":100.85,\"c\":101.3},{\"o\":101.3,\"h\":101.75,\"l\":101.2,\"c\":101.65},{\"o\":101.65,\"h\":101.95,\"l\":101.5,\"c\":101.6},{\"o\":101.6,\"h\":101.7,\"l\":101.1,\"c\":101.2},{\"o\":101.2,\"h\":101.3,\"l\":100.6,\"c\":100.7},{\"o\":100.7,\"h\":100.8,\"l\":100.05,\"c\":100.2},{\"o\":100.2,\"h\":100.7,\"l\":100.1,\"c\":100.65},{\"o\":100.65,\"h\":101.2,\"l\":100.55,\"c\":101.1},{\"o\":101.1,\"h\":101.6,\"l\":101,\"c\":101.5},{\"o\":101.5,\"h\":102,\"l\":101.4,\"c\":101.85},{\"o\":101.85,\"h\":101.95,\"l\":101.35,\"c\":101.45},{\"o\":101.45,\"h\":101.55,\"l\":100.95,\"c\":101.1},{\"o\":101.1,\"h\":101.6,\"l\":101,\"c\":101.55},{\"o\":101.55,\"h\":101.95,\"l\":101.45,\"c\":101.9},{\"o\":101.9,\"h\":102.6,\"l\":101.85,\"c\":102.55},{\"o\":102.55,\"h\":102.95,\"l\":102.45,\"c\":102.9},{\"o\":102.9,\"h\":103.05,\"l\":102.6,\"c\":102.7},{\"o\":102.7,\"h\":103.2,\"l\":102.65,\"c\":103.1},{\"o\":103.1,\"h\":103.45,\"l\":103,\"c\":103.4}],\"visible\":15,\"layers\":[{\"kind\":\"level\",\"price\":102,\"role\":\"resistance\",\"label\":\"RANGE HIGH 102.00\"}]},\"choices\":[{\"id\":\"enter\",\"label\":\"Buy the breakout at 102.60\"},{\"id\":\"fade\",\"label\":\"Wait to fade a close back inside\"},{\"id\":\"aside\",\"label\":\"Stand aside\"}],\"after\":\"This one held: bar 16 closed at 102.90, and no bar dipped below 102.45, let alone closed back inside. Bought at 102.60 with the stop under 101.85: still open. The fade never triggered. Same range, the same kind of bar, opposite endings.\",\"concept\":\"breakout\"}],\"check\":[\"q-2.6.6-1\",\"q-2.6.6-2\",\"q-2.6.6-3\"],\"recap\":{\"takeaways\":[\"Failed breakout: a close beyond the level, then a close back inside within one to three bars.\",\"Trapped breakout buyers' stops sit back inside the range; their stop sells can fuel the drop.\",\"Decide only after the bar closes, and write the invalidation for the choice you make.\"],\"next\":\"Next, 2.6.7: one huge bar after a long move, and whether it shows momentum or exhaustion.\"}},\"2.6.7\":{\"unit\":\"2.6\",\"courseId\":\"2.6.7\",\"bridge\":\"In 2.6.1 runs of trend bars showed urgency, and in 2.4.6 ATR measured a normal bar. Here you score a move's strength against its exhaustion, flag climax bars of 2.5 ATR or more, use the distance from the EMA 20 (2.3.3), and state a probability.\",\"hook\":{\"prompt\":\"A bar three times the ATR closes at its high after a long rally. Breakout or climax?\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.25,\"l\":99.85,\"c\":100.15},{\"o\":100.15,\"h\":100.29,\"l\":99.84,\"c\":99.95},{\"o\":99.95,\"h\":100.25,\"l\":99.8,\"c\":100.05},{\"o\":100.05,\"h\":100.21,\"l\":99.84,\"c\":100},{\"o\":100,\"h\":100.36,\"l\":99.87,\"c\":100.2},{\"o\":100.2,\"h\":100.33,\"l\":99.76,\"c\":99.95},{\"o\":99.95,\"h\":100.12,\"l\":99.8,\"c\":100},{\"o\":100,\"h\":100.32,\"l\":99.8,\"c\":100.15},{\"o\":100.15,\"h\":100.3,\"l\":99.94,\"c\":100.05},{\"o\":100.05,\"h\":100.23,\"l\":99.86,\"c\":100.1},{\"o\":100.1,\"h\":100.27,\"l\":99.78,\"c\":99.95},{\"o\":99.95,\"h\":100.21,\"l\":99.82,\"c\":100.05},{\"o\":100.05,\"h\":100.39,\"l\":99.98,\"c\":100.35},{\"o\":100.35,\"h\":100.66,\"l\":100.31,\"c\":100.63},{\"o\":100.63,\"h\":100.71,\"l\":100.43,\"c\":100.51},{\"o\":100.51,\"h\":100.87,\"l\":100.46,\"c\":100.84},{\"o\":100.84,\"h\":101.21,\"l\":100.78,\"c\":101.14},{\"o\":101.14,\"h\":101.39,\"l\":101.08,\"c\":101.36},{\"o\":101.36,\"h\":101.46,\"l\":101.15,\"c\":101.21},{\"o\":101.21,\"h\":101.58,\"l\":101.18,\"c\":101.51},{\"o\":101.51,\"h\":101.89,\"l\":101.44,\"c\":101.83},{\"o\":101.83,\"h\":102.17,\"l\":101.79,\"c\":102.1},{\"o\":102.1,\"h\":102.44,\"l\":102.03,\"c\":102.4},{\"o\":102.4,\"h\":102.5,\"l\":102.22,\"c\":102.3},{\"o\":102.3,\"h\":102.71,\"l\":102.23,\"c\":102.64},{\"o\":102.64,\"h\":102.99,\"l\":102.6,\"c\":102.94},{\"o\":102.94,\"h\":103.25,\"l\":102.91,\"c\":103.2},{\"o\":103.2,\"h\":103.58,\"l\":103.13,\"c\":103.51},{\"o\":103.51,\"h\":103.58,\"l\":103.31,\"c\":103.39},{\"o\":103.39,\"h\":103.75,\"l\":103.33,\"c\":103.72},{\"o\":103.72,\"h\":104.09,\"l\":103.66,\"c\":104.02},{\"o\":104.02,\"h\":104.4,\"l\":103.96,\"c\":104.34},{\"o\":104.34,\"h\":104.69,\"l\":104.29,\"c\":104.63},{\"o\":104.63,\"h\":104.96,\"l\":104.55,\"c\":104.89},{\"o\":104.89,\"h\":105.27,\"l\":104.82,\"c\":105.22},{\"o\":105.22,\"h\":105.57,\"l\":105.18,\"c\":105.52},{\"o\":105.52,\"h\":106.74,\"l\":105.49,\"c\":106.72}]},\"steps\":[{\"text\":\"Bar 37: range 1.25, about 3.1 times the ATR(14) of 0.40, closing 0.02 under its high.\"}]},\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"breakout\",\"label\":\"Breakout\",\"feedback\":\"It could be: big bars start legs too. But after 24 bars of rally, it could just as well end one.\"},{\"id\":\"climax\",\"label\":\"Climax\",\"feedback\":\"The context leans that way, but one bar can't settle it. Big bars also start new legs.\"},{\"id\":\"unclear\",\"label\":\"Can't tell from one bar\",\"feedback\":\"That's the honest answer: the reading is a probability, and only later bars confirm it.\"}],\"answer\":\"unclear\"},\"compare\":\"You picked {yours}. One bar can't settle it. The same big bar can start a leg or end one; context shifts the odds, and only the bars after it confirm.\",\"concept\":\"momentum-vs-exhaustion\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"Score a move by adding a point for each sign of strength and taking one away for each sign of exhaustion. Strength: runs of trend bars, low overlap, shallow pullbacks, closes near the extremes, gap bars. Exhaustion: a [[climax]] bar, distance from the EMA 20, rising overlap, tails against the move, no follow-through.\"},{\"kind\":\"match\",\"title\":\"Strength or exhaustion?\",\"prompt\":\"Sort each sign, for a rally. Strength adds 1 point, exhaustion takes 1 away; the score runs from −5 to +5.\",\"pairs\":[{\"left\":\"Three or more bull trend bars in a row\",\"right\":\"Strength +1\",\"wrong\":\"A run of trend bars is urgency: buyers winning bar after bar.\"},{\"left\":\"Average overlap of the last 5 bars under 30%\",\"right\":\"Strength +1\",\"wrong\":\"Little overlap means each bar moves on from the last: a sign of strength.\"},{\"left\":\"Pullbacks no deeper than 1 ATR\",\"right\":\"Strength +1\",\"wrong\":\"Shallow pullbacks mean sellers can't get much back: strength.\"},{\"left\":\"7 of the last 10 bars close in their top third\",\"right\":\"Strength +1\",\"wrong\":\"Closes near the highs, bar after bar, show buyers in control: strength.\"},{\"left\":\"A bar's low above the high of the bar two before it\",\"right\":\"Strength +1\",\"wrong\":\"That's a gap bar: price left a whole bar's range behind. A sign of strength.\"},{\"left\":\"A bar 2.5 ATR tall after 20 or more trend bars\",\"right\":\"Exhaustion −1\",\"wrong\":\"A huge bar late in a long move is the climax flag: often the last buyers rushing in.\"},{\"left\":\"Price more than 3 ATR above the EMA 20\",\"right\":\"Exhaustion −1\",\"wrong\":\"Far from its average, a move is stretched: an exhaustion flag.\"},{\"left\":\"Upper tails on each of the last 3 bars\",\"right\":\"Exhaustion −1\",\"wrong\":\"Tails on top mean higher prices were rejected: exhaustion, in a rally.\"},{\"left\":\"Overlap rising over the last 5 bars\",\"right\":\"Exhaustion −1\",\"wrong\":\"Rising overlap means bars stop moving on: the move is tiring.\"},{\"left\":\"No close above the big bar's close in the bars after it\",\"right\":\"Exhaustion −1\",\"wrong\":\"A big bar without follow-through is the clearest exhaustion flag.\"}],\"correct\":\"Strength shows as urgency: runs, little overlap, small pullbacks. [[exhaustion|Exhaustion]] shows as stretch and hesitation.\",\"concept\":\"momentum-vs-exhaustion\"},{\"kind\":\"figure\",\"title\":\"The climax detector\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.25,\"l\":99.85,\"c\":100.15},{\"o\":100.15,\"h\":100.29,\"l\":99.84,\"c\":99.95},{\"o\":99.95,\"h\":100.25,\"l\":99.8,\"c\":100.05},{\"o\":100.05,\"h\":100.21,\"l\":99.84,\"c\":100},{\"o\":100,\"h\":100.36,\"l\":99.87,\"c\":100.2},{\"o\":100.2,\"h\":100.33,\"l\":99.76,\"c\":99.95},{\"o\":99.95,\"h\":100.12,\"l\":99.8,\"c\":100},{\"o\":100,\"h\":100.32,\"l\":99.8,\"c\":100.15},{\"o\":100.15,\"h\":100.3,\"l\":99.94,\"c\":100.05},{\"o\":100.05,\"h\":100.23,\"l\":99.86,\"c\":100.1},{\"o\":100.1,\"h\":100.27,\"l\":99.78,\"c\":99.95},{\"o\":99.95,\"h\":100.21,\"l\":99.82,\"c\":100.05},{\"o\":100.05,\"h\":100.39,\"l\":99.98,\"c\":100.35},{\"o\":100.35,\"h\":100.66,\"l\":100.31,\"c\":100.63},{\"o\":100.63,\"h\":100.71,\"l\":100.43,\"c\":100.51},{\"o\":100.51,\"h\":100.87,\"l\":100.46,\"c\":100.84},{\"o\":100.84,\"h\":101.21,\"l\":100.78,\"c\":101.14},{\"o\":101.14,\"h\":101.39,\"l\":101.08,\"c\":101.36},{\"o\":101.36,\"h\":101.46,\"l\":101.15,\"c\":101.21},{\"o\":101.21,\"h\":101.58,\"l\":101.18,\"c\":101.51},{\"o\":101.51,\"h\":101.89,\"l\":101.44,\"c\":101.83},{\"o\":101.83,\"h\":102.17,\"l\":101.79,\"c\":102.1},{\"o\":102.1,\"h\":102.44,\"l\":102.03,\"c\":102.4},{\"o\":102.4,\"h\":102.5,\"l\":102.22,\"c\":102.3},{\"o\":102.3,\"h\":102.71,\"l\":102.23,\"c\":102.64},{\"o\":102.64,\"h\":102.99,\"l\":102.6,\"c\":102.94},{\"o\":102.94,\"h\":103.25,\"l\":102.91,\"c\":103.2},{\"o\":103.2,\"h\":103.58,\"l\":103.13,\"c\":103.51},{\"o\":103.51,\"h\":103.58,\"l\":103.31,\"c\":103.39},{\"o\":103.39,\"h\":103.75,\"l\":103.33,\"c\":103.72},{\"o\":103.72,\"h\":104.09,\"l\":103.66,\"c\":104.02},{\"o\":104.02,\"h\":104.4,\"l\":103.96,\"c\":104.34},{\"o\":104.34,\"h\":104.69,\"l\":104.29,\"c\":104.63},{\"o\":104.63,\"h\":104.96,\"l\":104.55,\"c\":104.89},{\"o\":104.89,\"h\":105.27,\"l\":104.82,\"c\":105.22},{\"o\":105.22,\"h\":105.57,\"l\":105.18,\"c\":105.52},{\"o\":105.52,\"h\":106.74,\"l\":105.49,\"c\":106.72}]},\"steps\":[{\"text\":\"Bars 13 to 36: a 24-bar rally, mostly bull trend bars.\",\"layers\":[{\"kind\":\"marker\",\"index\":12,\"at\":\"low\",\"label\":\"RALLY STARTS\",\"role\":\"up\"}]},{\"text\":\"Bar 37: range 1.25, about 3.1 × the ATR(14) of 0.40 before it.\",\"layers\":[{\"kind\":\"marker\",\"index\":36,\"at\":\"high\",\"label\":\"3.1 ATR\",\"role\":\"accent\"}]},{\"text\":\"It closes 3.09 above the EMA 20, 103.63: far beyond 3 ATR, 1.20.\",\"layers\":[{\"kind\":\"line\",\"role\":\"concept\",\"label\":\"EMA 20\",\"values\":[null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,100.41,100.54,100.69,100.85,100.99,101.15,101.32,101.5,101.69,101.85,102.03,102.22,102.42,102.63,102.85,103.07,103.31,103.63]}]}]},\"text\":\"The app flags a [[climax]] bar when its range is at least 2.5 ATR after 20 or more bars of trend. Context adds weight: the distance from the EMA 20, and whether the next bars follow through.\",\"concept\":\"momentum-vs-exhaustion\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"The same big bar reads two ways. After a quiet range, it's a breakout candidate. After 24 trend bars and far from the EMA, it's a climax candidate. Context shifts the odds; it doesn't settle them. Write down a probability, not a certainty.\"},{\"kind\":\"predict\",\"title\":\"How likely?\",\"prompt\":\"Will any of the next 5 bars close above bar 37's close, 106.72? Give your probability.\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":100,\"step\":10,\"unit\":\"%\",\"start\":50,\"feedback\":[{\"from\":0,\"to\":30,\"text\":\"Outcome: no. Your Brier score for this one: 0.09 or less. Lower is better.\"},{\"from\":40,\"to\":60,\"text\":\"Outcome: no. Your Brier score for this one: between 0.16 and 0.36.\"},{\"from\":70,\"to\":100,\"text\":\"Outcome: no. Your Brier score for this one: 0.49 to 1.00. Confidence costs most when it's wrong.\"}]},\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":100,\"h\":100.25,\"l\":99.85,\"c\":100.15},{\"o\":100.15,\"h\":100.29,\"l\":99.84,\"c\":99.95},{\"o\":99.95,\"h\":100.25,\"l\":99.8,\"c\":100.05},{\"o\":100.05,\"h\":100.21,\"l\":99.84,\"c\":100},{\"o\":100,\"h\":100.36,\"l\":99.87,\"c\":100.2},{\"o\":100.2,\"h\":100.33,\"l\":99.76,\"c\":99.95},{\"o\":99.95,\"h\":100.12,\"l\":99.8,\"c\":100},{\"o\":100,\"h\":100.32,\"l\":99.8,\"c\":100.15},{\"o\":100.15,\"h\":100.3,\"l\":99.94,\"c\":100.05},{\"o\":100.05,\"h\":100.23,\"l\":99.86,\"c\":100.1},{\"o\":100.1,\"h\":100.27,\"l\":99.78,\"c\":99.95},{\"o\":99.95,\"h\":100.21,\"l\":99.82,\"c\":100.05},{\"o\":100.05,\"h\":100.39,\"l\":99.98,\"c\":100.35},{\"o\":100.35,\"h\":100.66,\"l\":100.31,\"c\":100.63},{\"o\":100.63,\"h\":100.71,\"l\":100.43,\"c\":100.51},{\"o\":100.51,\"h\":100.87,\"l\":100.46,\"c\":100.84},{\"o\":100.84,\"h\":101.21,\"l\":100.78,\"c\":101.14},{\"o\":101.14,\"h\":101.39,\"l\":101.08,\"c\":101.36},{\"o\":101.36,\"h\":101.46,\"l\":101.15,\"c\":101.21},{\"o\":101.21,\"h\":101.58,\"l\":101.18,\"c\":101.51},{\"o\":101.51,\"h\":101.89,\"l\":101.44,\"c\":101.83},{\"o\":101.83,\"h\":102.17,\"l\":101.79,\"c\":102.1},{\"o\":102.1,\"h\":102.44,\"l\":102.03,\"c\":102.4},{\"o\":102.4,\"h\":102.5,\"l\":102.22,\"c\":102.3},{\"o\":102.3,\"h\":102.71,\"l\":102.23,\"c\":102.64},{\"o\":102.64,\"h\":102.99,\"l\":102.6,\"c\":102.94},{\"o\":102.94,\"h\":103.25,\"l\":102.91,\"c\":103.2},{\"o\":103.2,\"h\":103.58,\"l\":103.13,\"c\":103.51},{\"o\":103.51,\"h\":103.58,\"l\":103.31,\"c\":103.39},{\"o\":103.39,\"h\":103.75,\"l\":103.33,\"c\":103.72},{\"o\":103.72,\"h\":104.09,\"l\":103.66,\"c\":104.02},{\"o\":104.02,\"h\":104.4,\"l\":103.96,\"c\":104.34},{\"o\":104.34,\"h\":104.69,\"l\":104.29,\"c\":104.63},{\"o\":104.63,\"h\":104.96,\"l\":104.55,\"c\":104.89},{\"o\":104.89,\"h\":105.27,\"l\":104.82,\"c\":105.22},{\"o\":105.22,\"h\":105.57,\"l\":105.18,\"c\":105.52},{\"o\":105.52,\"h\":106.74,\"l\":105.49,\"c\":106.72},{\"o\":106.72,\"h\":106.82,\"l\":106.32,\"c\":106.54},{\"o\":106.54,\"h\":106.8,\"l\":106.39,\"c\":106.58},{\"o\":106.58,\"h\":106.82,\"l\":106.26,\"c\":106.36},{\"o\":106.36,\"h\":106.64,\"l\":106.18,\"c\":106.44},{\"o\":106.44,\"h\":106.59,\"l\":106.07,\"c\":106.19}],\"visible\":37,\"layers\":[{\"kind\":\"line\",\"role\":\"concept\",\"label\":\"EMA 20\",\"values\":[null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,100.41,100.54,100.69,100.85,100.99,101.15,101.32,101.5,101.69,101.85,102.03,102.22,102.42,102.63,102.85,103.07,103.31,103.63,103.91,104.16,104.37,104.57,104.72]}]},\"steps\":[{\"text\":\"The next five closes: 106.54, 106.58, 106.36, 106.44, 106.19. None above 106.72.\",\"visible\":42}]},\"reveal\":\"No continuation this time. One outcome can't grade one forecast: a [[brier-score]] averages (probability − outcome)² over many forecasts. 0 is perfect; always saying 50% earns 0.25.\",\"concept\":\"momentum-vs-exhaustion\"},{\"kind\":\"worked\",\"title\":\"Scoring three forecasts\",\"lines\":[\"Brier score: the average of (your probability − outcome)², with outcome 1 if it happened and 0 if not.\",\"Forecast 1: 0.70, didn't happen. (0.70 − 0)² = 0.49.\",\"Forecast 2: 0.60, happened. (0.60 − 1)² = 0.16.\",\"Forecast 3: 0.90, happened. (0.90 − 1)² = 0.01.\",\"Average of the three = ?\"],\"ask\":{\"answer\":0.22,\"tolerance\":0.005,\"feedback\":[{\"value\":0.66,\"text\":\"That's the sum. Divide by the 3 forecasts.\"}],\"correct\":\"Right: 0.66 ÷ 3 = 0.22.\"},\"after\":\"0.22, a little better than the 0.25 that always saying 50% earns. Calibration builds over weeks: of all the times you say 70%, about 70% should happen.\",\"concept\":\"momentum-vs-exhaustion\"},{\"kind\":\"worked\",\"title\":\"Score move A\",\"lines\":[\"Move A: a rally in progress. ATR 0.45.\",\"The last 4 bars are all bull trend bars. Average overlap of the last 5: 22%.\",\"Deepest pullback so far: 0.35. Closes in the top third: 8 of the last 10.\",\"No gap bars.\",\"No bar taller than 1.4 ATR. The close is 2.1 ATR above the EMA 20.\",\"Overlap falling, no upper tails, still making new highs.\",\"Score, from −5 to +5 = ?\"],\"ask\":{\"answer\":4,\"tolerance\":0,\"feedback\":[{\"value\":5,\"text\":\"There are no gap bars, so that point is missing.\"},{\"value\":3,\"text\":\"Recount the strength side: the run, the overlap, the pullbacks and the closes all pass. Only gap bars are missing.\"}],\"correct\":\"Right: 4 points of strength, no exhaustion flag.\"},\"after\":\"+4: strength on four counts and no flag of exhaustion. That describes the move so far. It isn't the probability that it continues.\",\"concept\":\"momentum-vs-exhaustion\"},{\"kind\":\"worked\",\"title\":\"Score move B\",\"lines\":[\"Move B: another rally, three bars after a big bar. ATR 0.45.\",\"Trend bars in a row now: none. Average overlap of the last 5: 61%, up from 25%.\",\"Deepest pullback in the rally: 0.40. Closes in the top third: 5 of the last 10. No gap bars.\",\"The big bar was 3.1 ATR tall, after 24 trend bars. The close is 3.4 ATR above the EMA 20.\",\"Upper tails on each of the last 3 bars. No close above the big bar's close since.\",\"Score, from −5 to +5 = ?\"],\"ask\":{\"answer\":-4,\"tolerance\":0,\"feedback\":[{\"value\":-5,\"text\":\"One strength point survives: the deepest pullback, 0.40, is within 1 ATR. +1 − 5.\"},{\"value\":4,\"text\":\"Check the sign: five exhaustion flags at −1 each, one strength point.\"}],\"correct\":\"Right: +1 − 5 = −4.\"},\"after\":\"Move A scores +4, move B −4. The score describes the move; your probability is the forecast, and over many forecasts the Brier score shows how good they are.\",\"concept\":\"momentum-vs-exhaustion\"}],\"check\":[\"q-2.6.7-1\",\"q-2.6.7-2\",\"q-2.6.7-3\"],\"recap\":{\"takeaways\":[\"Score a move: +1 per sign of strength, −1 per sign of exhaustion, from −5 to +5.\",\"Climax flag: a bar at least 2.5 ATR tall after 20 or more trend bars.\",\"A big bar can start or end a move. State a probability, then track your Brier score.\"],\"next\":\"Next, 2.6.8: when the daily and the hourly chart disagree, a rule written in advance decides which one wins.\"}},\"2.6.8\":{\"unit\":\"2.6\",\"courseId\":\"2.6.8\",\"bridge\":\"In 1.5.8 you read the trend on a higher timeframe before timing the entry, and in 2.3.1 Dow Theory ran three trends at once. Here you pick three timeframes 4–6 times apart, write which one wins before trading, and spot timeframe shopping.\",\"hook\":{\"prompt\":\"The daily chart is in an uptrend. The hourly chart is falling. Which one wins?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"daily\",\"label\":\"The daily\",\"feedback\":\"Often a sound rule, but only if you wrote it before looking. Choosing per trade is how timeframe shopping starts.\"},{\"id\":\"hourly\",\"label\":\"The hourly\",\"feedback\":\"Same problem the other way round: the answer should come from a rule written in advance.\"},{\"id\":\"rule\",\"label\":\"Whatever my written rule says\",\"feedback\":\"Right: the hierarchy is decided before the trade.\"}],\"answer\":\"rule\"},\"compare\":\"You picked {yours}. The hierarchy is decided before the trade, not trade by trade. Otherwise you'll pick whichever chart agrees with you.\",\"concept\":\"timeframe-alignment\"},\"learn\":[{\"kind\":\"explain\",\"text\":\"Use three [[timeframe|timeframes]] about 4–6 times apart. The **higher** one gives the direction, the **trading** one gives the setup and the stop, and the **lower** one only times the entry. For example: 1D, 4H and 1H (6× and 4×), or 4H, 1H and 15m (4× and 4×).\"},{\"kind\":\"match\",\"title\":\"How far apart?\",\"prompt\":\"Sort each set of higher, trading and lower timeframes.\",\"pairs\":[{\"left\":\"1D, 4H, 1H\",\"right\":\"Fits 4–6×\",\"wrong\":\"1D is 6 × 4H, and 4H is 4 × 1H: both steps fit.\"},{\"left\":\"4H, 1H, 15m\",\"right\":\"Fits 4–6×\",\"wrong\":\"4× and 4×: both steps fit the guideline.\"},{\"left\":\"1H, 30m, 15m\",\"right\":\"Too close\",\"wrong\":\"2× steps: the three charts tell nearly the same story.\"},{\"left\":\"4H, 2H, 1H\",\"right\":\"Too close\",\"wrong\":\"2× steps again: the extra charts add little information.\"},{\"left\":\"1W, 1H, 1m\",\"right\":\"Too far\",\"wrong\":\"168× and 60×: the charts no longer connect.\"}],\"correct\":\"4–6× keeps each chart different enough to add information, and close enough to connect.\",\"concept\":\"timeframe-alignment\"},{\"kind\":\"order\",\"prompt\":\"Put the default hierarchy in order, from the rule that ranks first.\",\"items\":[\"Higher timeframe: sets the direction. If it's a range, there's no direction to follow.\",\"Trading timeframe: gives the setup and the stop.\",\"Lower timeframe: only times the entry. It can't overrule the other two.\"],\"explain\":\"The order is the point: a lower timeframe can time an entry, but never overrule the direction or move the stop.\",\"note\":{\"key\":\"mtf-rule\",\"label\":\"Your hierarchy rule, in one sentence\",\"placeholder\":\"e.g. Trade only in the 4H direction; stop on 1H structure; time entries on 15m.\"},\"concept\":\"timeframe-alignment\"},{\"kind\":\"explain\",\"text\":\"Alexander Elder's [[triple-screen]] is one written version: the trend on a timeframe about 5× longer, an oscillator moving against it on the trading timeframe, and an entry with a buy stop above the previous bar. The research behind this course couldn't verify his original description, so treat it as an example, not a tested system.\"},{\"kind\":\"hotspot\",\"title\":\"Stop on the trading timeframe\",\"prompt\":\"Your rule: trade in the 4H direction, up; set the stop on 1H structure. Tap the 1H low your stop goes under.\",\"chart\":{\"candles\":[{\"o\":100.8,\"h\":101,\"l\":100.7,\"c\":100.95},{\"o\":100.95,\"h\":101.2,\"l\":100.85,\"c\":101.1},{\"o\":101.1,\"h\":101.15,\"l\":100.75,\"c\":100.8},{\"o\":100.8,\"h\":100.85,\"l\":100.6,\"c\":100.75},{\"o\":100.75,\"h\":101.1,\"l\":100.7,\"c\":101.05},{\"o\":101.05,\"h\":101.45,\"l\":101,\"c\":101.4},{\"o\":101.4,\"h\":101.8,\"l\":101.35,\"c\":101.75},{\"o\":101.75,\"h\":102.05,\"l\":101.7,\"c\":101.95},{\"o\":101.95,\"h\":102,\"l\":101.65,\"c\":101.7},{\"o\":101.7,\"h\":101.75,\"l\":101.45,\"c\":101.5},{\"o\":101.5,\"h\":101.6,\"l\":101.4,\"c\":101.55},{\"o\":101.55,\"h\":101.85,\"l\":101.5,\"c\":101.8},{\"o\":101.8,\"h\":101.95,\"l\":101.62,\"c\":101.9},{\"o\":101.9,\"h\":102,\"l\":101.75,\"c\":101.85}]},\"zones\":[{\"id\":\"old\",\"label\":\"Bar 4 low, 100.60\",\"index\":3,\"price\":100.6,\"feedback\":\"That's an older swing low. The setup is wrong as soon as the last swing low breaks, 0.80 higher.\"},{\"id\":\"last\",\"label\":\"Bar 11 low, 101.40\",\"index\":10,\"price\":101.4},{\"id\":\"now\",\"label\":\"Bar 14 low, 101.75\",\"index\":13,\"price\":101.75,\"feedback\":\"That's just the current bar's low, not structure. Small wiggles like this belong to the lower timeframe, which only times the entry.\"}],\"answer\":\"last\",\"correct\":\"The last 1H swing low, 101.40. Below it, the 1H pullback setup is wrong. A 15m low would be too close: the lower timeframe times the entry, it doesn't set the stop.\",\"concept\":\"timeframe-alignment\"},{\"kind\":\"predict\",\"prompt\":\"Your written rule: trade only in the 4H direction. The 4H is rising; the 1H shows a clean sell setup. What do you do?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"short\",\"label\":\"Take the short: the setup is clean\",\"feedback\":\"The setup is on the trading timeframe, but your rule ranks the 4H first. Shorts are off the table.\"},{\"id\":\"skip\",\"label\":\"Skip it, and wait for a 1H buy setup\",\"feedback\":\"Right.\"},{\"id\":\"daily\",\"label\":\"Check the daily to break the tie\",\"feedback\":\"That's timeframe shopping: looking for a chart that agrees. Your rule already decided.\"}],\"answer\":\"skip\"},\"reveal\":\"Your rule decided before the chart did. Skipping a clean-looking setup is part of following a hierarchy; switching charts until one agrees is [[timeframe-shopping]].\",\"concept\":\"timeframe-alignment\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"No robust studies show directly that aligning timeframes improves results: [[evidence-grade]] D. It's plausible as a trend filter, given the evidence for momentum. But every extra timeframe adds choices, and with them the risk of overfitting and of timeframe shopping.\"}],\"task\":{\"widget\":\"bias-spotter\",\"data\":{\"options\":[{\"id\":\"followed\",\"label\":\"Followed the rule\"},{\"id\":\"shopping\",\"label\":\"Timeframe shopping\"},{\"id\":\"change\",\"label\":\"Proper rule change\"}],\"cards\":[{\"id\":\"j1\",\"text\":\"Lost on a 1H long. Ten minutes later I switched to the 15m, found a buy signal there and went long again.\",\"answer\":\"shopping\",\"correct\":\"A switch right after a loss, to a chart that offers a fresh entry: timeframe shopping.\",\"rationales\":{\"followed\":\"The rule didn't change; the chart did, ten minutes after a loss. That's the shopping pattern.\",\"change\":\"Rule changes happen in a review, in writing, not ten minutes after a loss.\"}},{\"id\":\"j2\",\"text\":\"Wrote the 4H bias, up, at 09:00. Took a 1H pullback long, timed on the 15m, stop under the 1H swing low.\",\"answer\":\"followed\",\"correct\":\"Direction from the 4H, setup and stop from the 1H, timing from the 15m: the hierarchy as written.\",\"rationales\":{\"shopping\":\"Every timeframe did the job the rule gave it, and the bias was written first. Nothing was shopped.\",\"change\":\"Nothing changed: the trader applied the rule already written.\"}},{\"id\":\"j3\",\"text\":\"The 4H was falling. The 1H looked bullish, so I opened the daily: rising. I went long on the daily's word.\",\"answer\":\"shopping\",\"correct\":\"The trader looked for a chart that agreed with the long they wanted. That's timeframe shopping.\",\"rationales\":{\"followed\":\"The rule ranks the 4H first, and it was falling. Opening the daily to overrule it breaks the rule.\",\"change\":\"A new hierarchy chosen mid-trade, to justify one entry, isn't a rule change. It's shopping.\"}},{\"id\":\"j4\",\"text\":\"The 4H was in a range: no direction. I skipped a 1H buy setup, as my rule says.\",\"answer\":\"followed\",\"correct\":\"No direction on the higher timeframe, so no trade in its direction. Skipping is following the rule.\",\"rationales\":{\"shopping\":\"No timeframe was switched to find agreement. The trader stood aside, as written.\",\"change\":\"The rule was applied, not changed.\"}},{\"id\":\"j5\",\"text\":\"Weekend review of 40 journaled trades. I wrote a new rule for next week: 1D, 4H, 1H.\",\"answer\":\"change\",\"correct\":\"Changed in a review, on a sample of trades, in writing, before the next session: a proper rule change.\",\"rationales\":{\"followed\":\"Here the rule itself changed. What makes it proper is when and how: in a review, written down.\",\"shopping\":\"Shopping happens trade by trade, to justify an entry. This change came from a review of 40 trades.\"}},{\"id\":\"j6\",\"text\":\"Long with the 4H. A sharp 15m drop scared me, so I closed and went short on the 15m.\",\"answer\":\"shopping\",\"correct\":\"The 15m overruled the 4H bias mid-trade. The lower timeframe only times entries; it can't flip the direction.\",\"rationales\":{\"followed\":\"The rule gives the 15m timing only. Letting it flip the direction breaks the hierarchy.\",\"change\":\"A rule change made in fear, mid-trade, is shopping for a chart that matches the feeling.\"}}]},\"goal\":\"Six journal entries. For each one, say whether the trader followed their timeframe rule, shopped for a timeframe, or changed the rule properly.\",\"success\":{\"field\":\"solved\",\"eq\":6},\"correct\":\"Six read. Shopping is a timeframe change that follows a feeling; a rule change follows a review.\",\"hints\":[\"Ask when the timeframe changed: after a loss or a scare, or in a calm review?\",\"A lower timeframe that overrules the higher one breaks the hierarchy.\"],\"showMe\":{\"solved\":6},\"concept\":\"timeframe-alignment\"},\"check\":[\"q-2.6.8-1\",\"q-2.6.8-2\",\"q-2.6.8-3\"],\"recap\":{\"takeaways\":[\"Pick three timeframes about 4–6× apart: direction, setup and stop, entry timing.\",\"Write the hierarchy before trading: the lower timeframe times entries and never overrules the higher.\",\"Switching charts after a loss, or to find agreement, is timeframe shopping. Change rules only in review.\"],\"next\":\"Next: the 2.6 checkpoint, then unit 2.7, Managing the trade, where signal bars and structure become entries, stops and exits.\"}}}");
